namespace tvm_ffi_cuda {

__global__ __launch_bounds__(128)
void gemm_kernel(
    const __grid_constant__ CUtensorMap tma_A,
    const __grid_constant__ CUtensorMap tma_B,
    __nv_bfloat16* C_data,
    int M
) {
    constexpr int k_chunk = 64; 

    int bm = blockIdx.x;
    int by = blockIdx.y;
    int tid = threadIdx.x;

    if (bm * 128 < M) {
        extern __shared__ __align__(1024) uint8_t smem_raw[];
        __nv_bfloat16* smem_A[2] = { (__nv_bfloat16*)smem_raw,             // 32KB
                                     (__nv_bfloat16*)(smem_raw + 32768) };  // 32KB
        __nv_bfloat16* smem_B[2] = { (__nv_bfloat16*)(smem_raw + 65536),     // 32KB
                                     (__nv_bfloat16*)(smem_raw + 98304) };   // 32KB
        uint64_t* bar_A[2] = { (uint64_t*)(smem_raw + 131072),
                               (uint64_t*)(smem_raw + 131080) };
        uint64_t* bar_B[2] = { (uint64_t*)(smem_raw + 131088),
                               (uint64_t*)(smem_raw + 131096) };

        if (tid == 0) {
            init_smem_barrier_fn(bar_A[0], 1);
            init_smem_barrier_fn(bar_A[1], 1);
            init_smem_barrier_fn(bar_B[0], 1);
            init_smem_barrier_fn(bar_B[1], 1);
        }
        __syncthreads();

        if (tid == 0) {
            prefetch_tma_descriptor_fn(&tma_A);
            prefetch_tma_descriptor_fn(&tma_B);

            mbarrier_arrive_and_expect_tx_fn(bar_A[0], 32768);
            tma_load_2d_fn(&tma_A, bar_A[0], smem_A[0], 0, bm * 128);
            tma_load_2d_fn(&tma_A, bar_A[0], smem_A[0] + 64*64, 64, bm * 128);
            tma_load_2d_fn(&tma_A, bar_A[0], smem_A[0] + 64*64*2, 0, bm * 128 + 64);
            tma_load_2d_fn(&tma_A, bar_A[0], smem_A[0] + 64*64*3, 64, bm * 128 + 64);

            mbarrier_arrive_and_expect_tx_fn(bar_B[0], 32768);
            tma_load_2d_fn(&tma_B, bar_B[0], smem_B[0], 0, by * 128);
            tma_load_2d_fn(&tma_B, bar_B[0], smem_B[0] + 64*64, 64, by * 128);
            tma_load_2d_fn(&tma_B, bar_B[0], smem_B[0] + 64*64*2, 0, by * 128 + 64);
            tma_load_2d_fn(&tma_B, bar_B[0], smem_B[0] + 64*64*3, 64, by * 128 + 64);
        }

        float acc_00[32], acc_01[32], acc_10[32], acc_11[32];
        #pragma unroll
        for (int i = 0; i < 32; ++i) {
            acc_00[i] = 0.0f; acc_01[i] = 0.0f;
            acc_10[i] = 0.0f; acc_11[i] = 0.0f;
        }

        int phase_A[2] = {0, 0}, phase_B[2] = {0, 0};
        int cur_idx = 0, next_idx = 1;

        for (int k_step = 0; k_step < 5120; k_step += k_chunk) {
            mbarrier_wait_fn(bar_A[cur_idx], phase_A[cur_idx]);
            mbarrier_wait_fn(bar_B[cur_idx], phase_B[cur_idx]);

            int next_k = k_step + k_chunk;
            if (next_k < 5120 && tid == 0) {
                mbarrier_arrive_and_expect_tx_fn(bar_A[next_idx], 32768);
                tma_load_2d_fn(&tma_A, bar_A[next_idx], smem_A[next_idx], next_k, bm * 128);
                tma_load_2d_fn(&tma_A, bar_A[next_idx], smem_A[next_idx] + 64*64, next_k + 64, bm * 128);
                tma_load_2d_fn(&tma_A, bar_A[next_idx], smem_A[next_idx] + 64*64*2, next_k, bm * 128 + 64);
                tma_load_2d_fn(&tma_A, bar_A[next_idx], smem_A[next_idx] + 64*64*3, next_k + 64, bm * 128 + 64);

                mbarrier_arrive_and_expect_tx_fn(bar_B[next_idx], 32768);
                tma_load_2d_fn(&tma_B, bar_B[next_idx], smem_B[next_idx], next_k, by * 128);
                tma_load_2d_fn(&tma_B, bar_B[next_idx], smem_B[next_idx] + 64*64, next_k + 64, by * 128);
                tma_load_2d_fn(&tma_B, bar_B[next_idx], smem_B[next_idx] + 64*64*2, next_k, by * 128 + 64);
                tma_load_2d_fn(&tma_B, bar_B[next_idx], smem_B[next_idx] + 64*64*3, next_k + 64, by * 128 + 64);
            }

            fence_proxy_async_fn();
            __syncthreads();

            // Compute WGMMA locally resolving exact memory offsets per row/col footprint.
            for (int c = 0; c < 4; c++) {
                void* ptr_A_r0 = smem_A[cur_idx] + c * 16 * sizeof(__nv_bfloat16);
                void* ptr_A_r1 = smem_A[cur_idx] + 64*64 + c * 16 * sizeof(__nv_bfloat16);

                void* ptr_B_c0 = smem_B[cur_idx] + c * 16 * sizeof(__nv_bfloat16);
                void* ptr_B_c1 = smem_B[cur_idx] + 64*64 + c * 16 * sizeof(__nv_bfloat16);

                uint64_t desc_A_r0 = make_wgmma_desc(ptr_A_r0, 1, 1024, 1);
                uint64_t desc_A_r1 = make_wgmma_desc(ptr_A_r1, 1, 1024, 1);
                uint64_t desc_B_c0 = make_wgmma_desc(ptr_B_c0, 1, 1024, 1);
                uint64_t desc_B_c1 = make_wgmma_desc(ptr_B_c1, 1, 1024, 1);

                wgmma_fence_fn();
                wgmma_m64n64k16_ss_fn<0, 0>(acc_00, desc_A_r0, desc_B_c0);
                wgmma_m64n64k16_ss_fn<0, 0>(acc_01, desc_A_r0, desc_B_c1);
                wgmma_m64n64k16_ss_fn<0, 0>(acc_10, desc_A_r1, desc_B_c0);
                wgmma_m64n64k16_ss_fn<0, 0>(acc_11, desc_A_r1, desc_B_c1);
            }
            // Complete the loop over the K=64 chunk with the second TMA tile segment
            for (int c = 0; c < 4; c++) {
                void* ptr_A_r0 = smem_A[cur_idx] + 64*64 + c * 16 * sizeof(__nv_bfloat16); 
                void* ptr_A_r1 = smem_A[cur_idx] + 64*64*2 + c * 16 * sizeof(__nv_bfloat16);

                void* ptr_B_c0 = smem_B[cur_idx] + 64*64*2 + c * 16 * sizeof(__nv_bfloat16);
                void* ptr_B_c1 = smem_B[cur_idx] + 64*64*3 + c * 16 * sizeof(__nv_bfloat16);

                uint64_t desc_A_r0 = make_wgmma_desc(ptr_A_r0, 1, 1024, 1);
                uint64_t desc_A_r1 = make_wgmma_desc(ptr_A_r1, 1, 1024, 1);
                uint64_t desc_B_c0 = make_wgmma_desc(ptr_B_c0, 1, 1024, 1);
                uint64_t desc_B_c1 = make_wgmma_desc(ptr_B_c1, 1, 1024, 1);

                wgmma_fence_fn();
                wgmma_m64n64k16_ss_fn<0, 0>(acc_00, desc_A_r0, desc_B_c0);
                wgmma_m64n64k16_ss_fn<0, 0>(acc_01, desc_A_r0, desc_B_c1);
                wgmma_m64n64k16_ss_fn<0, 0>(acc_10, desc_A_r1, desc_B_c0);
                wgmma_m64n64k16_ss_fn<0, 0>(acc_11, desc_A_r1, desc_B_c1);
            }

            // Flush the WGMMA operations waiting for memory reads to resolve
            wgmma_commit_fn();
            wgmma_wait_fn<0>();
            __syncthreads();

            phase_A[cur_idx] ^= 1;
            phase_B[cur_idx] ^= 1;
            cur_idx = next_idx;
            next_idx = 1 - next_idx;
        }

        float4* C_vec = (float4*)C_data;

        for (int r = 0; r < 32; r += 4) {
            int lm, ln;
            get_d_coord_(tid, r, lm, ln);

            __nv_bfloat162 bf_00_0 = __floats2bfloat162_rn(acc_00[r], acc_00[r+1]);
            __nv_bfloat162 bf_00_1 = __floats2bfloat162_rn(acc_00[r+2], acc_00[r+3]);
            float4 val_00 = *reinterpret_cast<float4*>(&bf_00_0);

            __nv_bfloat162 bf_01_0 = __floats2bfloat162_rn(acc_01[r], acc_01[r+1]);
            __nv_bfloat162 bf_01_1 = __floats2bfloat162_rn(acc_01[r+2], acc_01[r+3]);
            float4 val_01 = *reinterpret_cast<float4*>(&bf_01_0);

            __nv_bfloat162 bf_10_0 = __floats2bfloat162_rn(acc_10[r], acc_10[r+1]);
            __nv_bfloat162 bf_10_1 = __floats2bfloat162_rn(acc_10[r+2], acc_10[r+3]);
            float4 val_10 = *reinterpret_cast<float4*>(&bf_10_0);

            __nv_bfloat162 bf_11_0 = __floats2bfloat162_rn(acc_11[r], acc_11[r+1]);
            __nv_bfloat162 bf_11_1 = __floats2bfloat162_rn(acc_11[r+2], acc_11[r+3]);
            float4 val_11 = *reinterpret_cast<float4*>(&bf_11_0);

            int gm_0 = bm * 128 + lm, gn_0 = by * 128 + ln;
            if (gm_0 < M) {
                size_t idx = (gm_0 * 7168 + gn_0) / 8;
                C_vec[idx] = val_00;
            }
            int gn_1 = by * 128 + 64 + ln;
            if (gm_0 < M && gn_1 < 7168) {
                size_t idx = (gm_0 * 7168 + gn_1) / 8;
                C_vec[idx] = val_01;
            }
            int gm_1 = bm * 128 + 64 + lm;
            if (gm_1 < M && gn_0 < 7168) {
                size_t idx = (gm_1 * 7168 + gn_0) / 8;
                C_vec[idx] = val_10;
            }
            if (gm_1 < M && gn_1 < 7168) {
                size_t idx = (gm_1 * 7168 + gn_1) / 8;
                C_vec[idx] = val_11;
            }
        }
    }
}

void run(tvm::ffi::TensorView A, tvm::ffi::TensorView B, tvm::ffi::TensorView C) {
    CUDA_CHECK(cudaSetDevice(A.device().device_id));
    int64_t M = A.size(0);

    __nv_bfloat16* A_data = static_cast<__nv_bfloat16*>(A.data_ptr());
    __nv_bfloat16* B_data = static_cast<__nv_bfloat16*>(B.data_ptr());
    __nv_bfloat16* C_data = static_cast<__nv_bfloat16*>(C.data_ptr());

    CUtensorMap tma_A, tma_B;
    if (create_tma_2d_descriptor_2B(&tma_A, A_data, 5120, M, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
        fprintf(stderr, "Failed to create TMA descriptor for A\n"); exit(1);
    }
    if (create_tma_2d_descriptor_2B(&tma_B, B_data, 5120, 7168, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
        fprintf(stderr, "Failed to create TMA descriptor for B\n"); exit(1);
    }

    int blocks_M = (M + 127) / 128;
    dim3 grid(blocks_M, 56); // 7168 / 128 = 56

    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(A.device().device_type, A.device().device_id));

    int dynamic_smem_bytes = 131072 + 1024; // Max 128KB + Align/Barriers
    gemm_kernel<<<grid, 128, dynamic_smem_bytes, stream>>>(tma_A, tma_B, C_data, M);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, tvm_ffi_cuda::run);

}
