__device__ __forceinline__ void get_d_coord_(int tid, int reg, int& row, int& col) {
    int t0 = tid % 4, t1 = (tid / 4) % 8, t2 = tid / 32;
    int r0 = reg % 2, r1 = (reg / 2) % 2, r2 = reg / 4;
    int lin = t0 * 128 + t1 * 1 + t2 * 16 + r0 * 64 + r1 * 8 + r2 * 512;
    row = lin % 64; col = lin / 64;
}

__global__ void __launch_bounds__(128) gemm_kernel(
    const __grid_constant__ CUtensorMap tma_A,
    const __grid_constant__ CUtensorMap tma_B,
    __nv_bfloat16* C, int M, int N) 
{
    int tid = threadIdx.x;
    int bm = blockIdx.x;
    int bn = blockIdx.y * 4 * 64;
    int m_offset = bm * 64;

    constexpr int num_k_tiles = 80; 
    constexpr int num_n_tiles = 4;

    __shared__ __align__(1024) uint8_t smem_A[2][8192];       
    __shared__ __align__(1024) uint8_t smem_B[2][8192];   

    __shared__ __align__(8) uint64_t bar_init;
    __shared__ __align__(8) uint64_t bar_A[2];
    __shared__ __align__(8) uint64_t bar_B[2];

    if (tid == 0) {
        init_smem_barrier_fn(&bar_init, 128);
        init_smem_barrier_fn(&bar_A[0], 1);
        init_smem_barrier_fn(&bar_B[0], 1);
        init_smem_barrier_fn(&bar_A[1], 1);
        init_smem_barrier_fn(&bar_B[1], 1);
    }
    named_barrier_sync_fn(1, 128); 

    if (tid == 0) {
        fence_smem_barrier_init_fn();
    }
    named_barrier_sync_fn(1, 128);

    // Pre-issue first K-tile to overlap memory latency completely
    if (tid == 0 && num_k_tiles > 0) {
        mbarrier_arrive_and_expect_tx_fn(&bar_A[0], 8192);
        tma_load_2d_fn(&tma_A, &bar_A[0], smem_A[0], 0, m_offset);

        mbarrier_arrive_and_expect_tx_fn(&bar_B[0], 8192 * num_n_tiles);
        #pragma unroll
        for (int j = 0; j < num_n_tiles; j++) {
            tma_load_2d_fn(&tma_B, &bar_B[0], smem_B[0], 0, bn + j * 64);
        }
    }

    float acc_0[32];
    float acc_1[32];
    float acc_2[32];
    float acc_3[32];
    #pragma unroll
    for (int i = 0; i < 32; i++) {
        acc_0[i] = 0.0f; acc_1[i] = 0.0f; acc_2[i] = 0.0f; acc_3[i] = 0.0f;
    }

    int phase_A[2] = {0, 0};
    int phase_B[2] = {0, 0};

    for (int k = 0; k < num_k_tiles; k++) {
        int idx = k % 2;
        int next_idx = (k + 1) % 2;

        // 1. Schedule Next Mem Load Early (Ping-Pong)
        if (k + 1 < num_k_tiles) {
            if (tid == 0) {
                mbarrier_arrive_and_expect_tx_fn(&bar_A[next_idx], 8192);
                tma_load_2d_fn(&tma_A, &bar_A[next_idx], smem_A[next_idx], (k + 1) * 64, m_offset);

                mbarrier_arrive_and_expect_tx_fn(&bar_B[next_idx], 8192 * num_n_tiles);
                #pragma unroll
                for (int j = 0; j < num_n_tiles; j++) {
                    tma_load_2d_fn(&tma_B, &bar_B[next_idx], smem_B[next_idx], (k + 1) * 64, bn + j * 64);
                }
            }
        }

        // 2. Synchronize waiting for the Current Tile
        mbarrier_wait_fn(&bar_A[idx], phase_A[idx]);
        mbarrier_wait_fn(&bar_B[idx], phase_B[idx]);
        phase_A[idx] ^= 1;
        phase_B[idx] ^= 1;

        asm volatile("fence.proxy.async;\n" ::: "memory");
        __syncwarp();
        asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");

        float* acc_ptrs[4] = {acc_0, acc_1, acc_2, acc_3};

        // 3. Calculate locally to avoid divergence & shared dependency stalls
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            uint64_t da_i = make_wgmma_desc(smem_A[idx] + i * 32, 1, 1024, 1);
            #pragma unroll
            for (int j = 0; j < num_n_tiles; j++) {
                uint64_t db_ij = make_wgmma_desc(smem_B[idx] + i * 32, 1, 1024, 1);
                wgmma_m64n64k16_ss_fn<0, 0>(acc_ptrs[j], da_i, db_ij);
            }
        }

        asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
        asm volatile("wgmma.wait_group.sync.aligned 0;\n" :: "n"(0) : "memory");
    }

    #pragma unroll
    for (int r = 0; r < 32; r++) {
        int lm, ln;
        get_d_coord_(tid, r, lm, ln);
        int gm = bm * 64 + lm;
        if (gm < M) {
            float val[4] = {acc_0[r], acc_1[r], acc_2[r], acc_3[r]};
            #pragma unroll
            for (int j = 0; j < 4; j++) {
                int gn = bn + j * 64 + ln;
                if (gn < N) {
                    C[(int64_t)gm * N + gn] = __float2bfloat16(val[j]);
                }
            }
        }
    }
}

void run(tvm::ffi::TensorView A, tvm::ffi::TensorView B, tvm::ffi::TensorView C) {
    CUDA_CHECK(cudaSetDevice(A.device().device_id));
    int64_t M = A.size(0);
    int64_t N = B.size(0); 
    int64_t K = A.size(1); 

    __nv_bfloat16* A_data = static_cast<__nv_bfloat16*>(A.data_ptr());
    __nv_bfloat16* B_data = static_cast<__nv_bfloat16*>(B.data_ptr());
    __nv_bfloat16* C_data = static_cast<__nv_bfloat16*>(C.data_ptr());

    CUtensorMap tma_A, tma_B;
    create_tma_2d_descriptor_2B(&tma_A, A_data, K, M, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    create_tma_2d_descriptor_2B(&tma_B, B_data, K, N, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);

    int num_blocks_x = (M + 63) / 64;
    int num_blocks_y = (N / 64) / 4;
    dim3 grid(num_blocks_x, num_blocks_y, 1);
    dim3 block(128);

    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(A.device().device_type, A.device().device_id));

    cudaLaunchConfig_t config = {};
    config.gridDim = grid;
    config.blockDim = block;
    config.dynamicSmemBytes = 0;
    config.stream = stream;

    CUDA_CHECK(cudaLaunchKernelEx(&config, gemm_kernel, tma_A, tma_B, C_data, M, N));
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, tvm_ffi_cuda::run);

