__global__ void __launch_bounds__(128) gemm_kernel(
    const __grid_constant__ CUtensorMap tma_A_128,
    const __grid_constant__ CUtensorMap tma_B_64,
    __nv_bfloat16* C, int M, int N) 
{
    int tid = threadIdx.x;
    int bm = blockIdx.x;
    int bn = blockIdx.y;
    int m_offset = bm * 128;

    constexpr int NUM_STAGES = 2;

    __shared__ __align__(1024) uint8_t smem_A[2][16384];       
    __shared__ __align__(1024) uint8_t smem_B[2][4][8192];   

    __shared__ __align__(8) uint64_t bar_init;
    __shared__ __align__(8) uint64_t bar_A[NUM_STAGES];
    __shared__ __align__(8) uint64_t bar_B[NUM_STAGES];

    if (tid == 0) {
        init_smem_barrier_fn(&bar_init, 128);
        for (int i = 0; i < NUM_STAGES; i++) {
            init_smem_barrier_fn(&bar_A[i], 1);
            init_smem_barrier_fn(&bar_B[i], 1);
        }
    }
    named_barrier_sync_fn(1, 128); 

    if (tid == 0) {
        fence_smem_barrier_init_fn();
    }
    named_barrier_sync_fn(1, 128);

    // Issue initial TMA mem loads for stage 0
    if (tid == 0) {
        mbarrier_arrive_and_expect_tx_fn(&bar_A[0], 16384);
        tma_load_2d_fn(&tma_A_128, &bar_A[0], smem_A[0], 0, m_offset);

        mbarrier_arrive_and_expect_tx_fn(&bar_B[0], 4 * 8192);
        #pragma unroll
        for (int j = 0; j < 4; j++) {
            tma_load_2d_fn(&tma_B_64, &bar_B[0], smem_B[0][j], 0, bn * 256 + j * 64);
        }
    }

    float acc_0[32];
    float acc_1[32];

    int phase_A[NUM_STAGES] = {0};
    int phase_B[NUM_STAGES] = {0};

    __shared__ float smem_partial[2][4][32]; 

    for (int k_idx = 0; k_idx < 80; k_idx++) {
        int idx = k_idx % NUM_STAGES;
        int next_k = k_idx + 1;

        if (next_k < 80) {
            int next_idx = (k_idx + 1) % NUM_STAGES;
            if (tid == 0) {
                mbarrier_arrive_and_expect_tx_fn(&bar_A[next_idx], 16384);
                tma_load_2d_fn(&tma_A_128, &bar_A[next_idx], smem_A[next_idx], next_k * 64, m_offset);

                mbarrier_arrive_and_expect_tx_fn(&bar_B[next_idx], 4 * 8192);
                #pragma unroll
                for (int j = 0; j < 4; j++) {
                    tma_load_2d_fn(&tma_B_64, &bar_B[next_idx], smem_B[next_idx][j], next_k * 64, bn * 256 + j * 64);
                }
            }
        }

        mbarrier_wait_fn(&bar_A[idx], phase_A[idx]);
        mbarrier_wait_fn(&bar_B[idx], phase_B[idx]);
        phase_A[idx] ^= 1;
        phase_B[idx] ^= 1;

        asm volatile("fence.proxy.async;\n" ::: "memory");
        __syncwarp();
        asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");

        #pragma unroll
        for (int i = 0; i < 2; i++) {
            #pragma unroll
            for (int r = 0; r < 32; r++) { acc_0[r] = 0.0f; acc_1[r] = 0.0f; }

            #pragma unroll
            for (int k = 0; k < 4; k++) {
                uint64_t da = make_wgmma_desc(smem_A[idx] + i * 8192 + k * 32, 1, 1024, 1);
                #pragma unroll
                for (int j = 0; j < 4; j++) {
                    uint64_t db_j = make_wgmma_desc(smem_B[idx][j] + k * 2048, 8192, 1024, 1);
                    wgmma_m64n64k16_ss_fn<0, 1>(i == 0 ? acc_0 : acc_1, da, db_j);
                }
            }

            #pragma unroll
            for (int r = 0; r < 32; r++) {
                smem_partial[i][0][r] = acc_0[r];
                smem_partial[i][1][r] = acc_1[r];
            }
        }

        asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
        asm volatile("wgmma.wait_group.sync.aligned 0;\n" :: "n"(0) : "memory");
        __syncthreads();
    }

    #pragma unroll
    for (int r = 0; r < 32; r++) {
        int lm, ln;
        get_d_coord_(tid, r, lm, ln);
        float sum0 = 0, sum1 = 0;
        #pragma unroll
        for (int j = 0; j < 4; j++) {
            sum0 += smem_partial[0][j][r];
            sum1 += smem_partial[1][j][r];
        }
        int gm = bm * 128 + lm;
        if (gm < M) {
            int gn0 = bn * 256 + ln;
            int gn1 = bn * 256 + 64 + ln;
            if (gn0 < N) {
                C[(int64_t)gm * N + gn0] = __float2bfloat16(sum0);
            }
            if (gn1 < N) {
                C[(int64_t)gm * N + gn1] = __float2bfloat16(sum1);
            }
        }
    }
}

void run(tvm::ffi::TensorView A, tvm::ffi::TensorView B, tvm::ffi::TensorView C) {
    CUDA_CHECK(cudaSetDevice(A.device().device_id));
    int64_t M = A.size(0);
    int64_t N = B.size(0); 
    int64_t K = A.size(1); 

    __nv_bfloat16* A_data = static_cast<__nv_bfloat16*>(A.data_ptr());
    __nv_bfloat16* B_data = static_cast<__nv_bfloat16*>(B.data_ptr());
    __nv_bfloat16* C_data = static_cast<__nv_bfloat16*>(C.data_ptr());

    CUtensorMap tma_A_128, tma_B_64;
    create_tma_2d_descriptor_2B(&tma_A_128, A_data, K, M, 64, 128, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    create_tma_2d_descriptor_2B(&tma_B_64, B_data, K, N, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);

    int num_blocks_x = (M + 127) / 128;
    int num_blocks_y = N / 256;
    dim3 grid(num_blocks_x, num_blocks_y, 1);
    dim3 block(128);

    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(A.device().device_type, A.device().device_id));

    cudaLaunchConfig_t config = {};
    config.gridDim = grid;
    config.blockDim = block;
    config.dynamicSmemBytes = 0;
    config.stream = stream;

    CUDA_CHECK(cudaLaunchKernelEx(&config, gemm_kernel, tma_A_128, tma_B_64, C_data, M, N));
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, tvm_ffi_cuda::run);

