          "+f"(c[24]),"+f"(c[25]),"+f"(c[26]),"+f"(c[27]),"+f"(c[28]),"+f"(c[29]),"+f"(c[30]),"+f"(c[31])
        : "l"(da), "l"(db), "n"(trans_a), "n"(trans_b));
}

__device__ __forceinline__ void store_acc_global_bf16_packed_fn(
    __nv_bfloat16* C, float* a0, float* a1, float* a2, float* a3,
    int bm, int bn, int M, int N, int tid) {
    #pragma unroll
    for (int r = 0; r < 32; r += 2) {
        int lm, ln;
        get_d_coord_(tid, r, lm, ln);
        int gm = bm + lm, gn = bn + ln;
        if (gm < M) {
            __nv_bfloat162 res;
            if (gn < N) {
                res.x = __float2bfloat16(a0[r]);
                res.y = __float2bfloat16(a0[r+1]);
                *( (__nv_bfloat162*)(&C[(int64_t)gm * N + gn]) ) = res;
            }
            if (gn + 64 < N) {
                res.x = __float2bfloat16(a1[r]);
                res.y = __float2bfloat16(a1[r+1]);
                *( (__nv_bfloat162*)(&C[(int64_t)gm * N + gn + 64]) ) = res;
            }
            if (gn + 128 < N) {
                res.x = __float2bfloat16(a2[r]);
                res.y = __float2bfloat16(a2[r+1]);
                *( (__nv_bfloat162*)(&C[(int64_t)gm * N + gn + 128]) ) = res;
            }
            if (gn + 192 < N) {
                res.x = __float2bfloat16(a3[r]);
                res.y = __float2bfloat16(a3[r+1]);
                *( (__nv_bfloat162*)(&C[(int64_t)gm * N + gn + 192]) ) = res;
            }
        }
    }
}

namespace tvm_ffi_gemm {

CUresult create_tma_2d_descriptor_2B(CUtensorMap* d, void* globalAddress, uint64_t gmem_inner_dim, uint64_t gmem_outer_dim, uint32_t smem_inner_dim, uint32_t smem_outer_dim, CUtensorMapSwizzle swizzle, CUtensorMapL2promotion l2Promotion, CUtensorMapFloatOOBfill oobFill) {
    cuuint64_t globalDim[2] = {gmem_inner_dim, gmem_outer_dim};
    cuuint64_t globalStrides[1] = {gmem_inner_dim * 2};
    cuuint32_t boxDim[2] = {smem_inner_dim, smem_outer_dim};
    cuuint32_t elementStrides[2] = {1, 1};
    return cuTensorMapEncodeTiled(
        d,
        CU_TENSOR_MAP_DATA_TYPE_BFLOAT16,
        2, 
        globalAddress,
        globalDim,
        globalStrides,
        boxDim, 
        elementStrides,
        CU_TENSOR_MAP_INTERLEAVE_NONE,
        swizzle,
        l2Promotion,
        oobFill
    );
}

__global__ void __launch_bounds__(128) gemm_kernel(
    const __grid_constant__ CUtensorMap tma_A,
    const __grid_constant__ CUtensorMap tma_B,
    __nv_bfloat16* C,
    int M,
    int N
) {
    setmaxnreg_inc_sync_fn<248>();

    int tid = threadIdx.x;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int CtaId = bx % 2;
    int DivBx = bx / 2;

    int m_base = DivBx * 128 + CtaId * 64;
    int n_base = by * 256;

    __shared__ __align__(1024) __nv_bfloat16 smem_A[3][8192];   
    __shared__ __align__(1024) __nv_bfloat16 smem_B[3][16384];  
    __shared__ uint64_t mbar_A[3];
    __shared__ uint64_t mbar_B[3];

    if (tid == 0) {
        init_smem_barrier_fn(&mbar_A[0], 1);
        init_smem_barrier_fn(&mbar_A[1], 1);
        init_smem_barrier_fn(&mbar_A[2], 1);
        init_smem_barrier_fn(&mbar_B[0], 1);
        init_smem_barrier_fn(&mbar_B[1], 1);
        init_smem_barrier_fn(&mbar_B[2], 1);
    }
    fence_smem_barrier_init_fn();
    __syncthreads();

    float acc[4][32];
    #pragma unroll
    for (int i = 0; i < 32; i++) {
        acc[0][i] = 0.0f; acc[1][i] = 0.0f; acc[2][i] = 0.0f; acc[3][i] = 0.0f;
    }

    int stages = M > 0 ? 5120 / 64 : 0;

    if (stages > 0 && tid == 0) {
        if (CtaId == 0) {
            mbarrier_arrive_and_expect_tx_fn(&mbar_A[0], 16384);
            tma_load_2d_fn(&tma_A, &mbar_A[0], smem_A[0], 0, m_base);
            tma_load_2d_fn(&tma_A, &mbar_A[0], smem_A[0] + 4096, 0, m_base + 64);

            mbarrier_arrive_expect_tx_cluster_fn(&mbar_B[0], 32768, CtaId); 
            tma_load_multicast_2d_fn(&tma_B, &mbar_B[0], smem_B[0], 0, n_base, 3);
        }
        else {
            mbarrier_arrive_and_expect_tx_fn(&mbar_A[0], 16384);
            tma_load_2d_fn(&tma_A, &mbar_A[0], smem_A[0], 0, m_base);
            tma_load_2d_fn(&tma_A, &mbar_A[0], smem_A[0] + 4096, 0, m_base + 64);
        }
    }

    auto desc_A = [](void* ptr) { return make_wgmma_desc(ptr, 1, 1024, 1); };
    auto desc_B = [](void* ptr) { return make_wgmma_desc(ptr, 8192, 1024, 1); };

    int stage = 0;
    do {
        int my_bar = stage % 3;
        int next_bar = (stage + 1) % 3;
        int parity = (stage / 3) % 2;

        mbarrier_wait_fn(&mbar_A[my_bar], parity);
        mbarrier_wait_fn(&mbar_B[my_bar], parity);

        fence_proxy_async_fn();
        __syncwarp();
        wgmma_fence_fn();

        for (int half = 0; half < 2; half++) {
            for (int k_idx = 0; k_idx < 64; k_idx += 16) {
                __nv_bfloat16* pA = smem_A[my_bar] + half * 4096 + k_idx;
                uint64_t dA = desc_A(pA);
                #pragma unroll
                for (int n_idx = 0; n_idx < 4; n_idx++) {
                    __nv_bfloat16* pB = smem_B[my_bar] + n_idx * 4096 + k_idx * 2048;
                    uint64_t dB = desc_B(pB);
                    wgmma_m64n64k16_ss_fn<0, 1>(acc[n_idx], dA, dB);
                }
            }
        }

        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        if (stage + 1 < stages) {
            int next_k_total = (stage + 1) * 64;
            if (tid == 0) {
                if (CtaId == 0) {
                    mbarrier_arrive_and_expect_tx_fn(&mbar_A[next_bar], 16384);
                    tma_load_2d_fn(&tma_A, &mbar_A[next_bar], smem_A[next_bar], next_k_total, m_base);
                    tma_load_2d_fn(&tma_A, &mbar_A[next_bar], smem_A[next_bar] + 4096, next_k_total, m_base + 64);

                    mbarrier_arrive_expect_tx_cluster_fn(&mbar_B[next_bar], 32768, CtaId);
                    tma_load_multicast_2d_fn(&tma_B, &mbar_B[next_bar], smem_B[next_bar], next_k_total, n_base, 3);
                }
                else {
                    mbarrier_arrive_and_expect_tx_fn(&mbar_A[next_bar], 16384);
                    tma_load_2d_fn(&tma_A, &mbar_A[next_bar], smem_A[next_bar], next_k_total, m_base);
                    tma_load_2d_fn(&tma_A, &mbar_A[next_bar], smem_A[next_bar] + 4096, next_k_total, m_base + 64);
                }
            }
        }

        __syncthreads();

    } while (stages > 0 && ++stage < stages);

    store_acc_global_bf16_packed_fn(C, acc[0], acc[1], acc[2], acc[3], m_base, n_base, M, N, tid);
}

void run(tvm::ffi::TensorView A, tvm::ffi::TensorView B, tvm::ffi::TensorView C) {
    CUDA_CHECK(cudaSetDevice(A.device().device_id));
    int M = A.size(0);
    int N = 7168;

    __nv_bfloat16* A_ptr = static_cast<__nv_bfloat16*>(A.data_ptr());
    __nv_bfloat16* B_ptr = static_cast<__nv_bfloat16*>(B.data_ptr());
    __nv_bfloat16* C_ptr = static_cast<__nv_bfloat16*>(C.data_ptr());

    CUtensorMap tma_A, tma_B;
    if (create_tma_2d_descriptor_2B(&tma_A, A_ptr, 5120, M, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
        fprintf(stderr, "Failed to create TMA descriptor for A\n");
        exit(1);
    }
    if (create_tma_2d_descriptor_2B(&tma_B, B_ptr, 7168, 5120, 256, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
        fprintf(stderr, "Failed to create TMA descriptor for B\n");
        exit(1);
    }

    int grid_x = ((M + 63) / 64 + 1) / 2;
    int grid_y = 7168 / 256; 
    dim3 grid(grid_x, grid_y);
    dim3 block(128);

    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(A.device().device_type, A.device().device_id));

    cudaLaunchConfig_t config = {};
    config.gridDim = grid;
    config.blockDim = block;
    config.dynamicSmemBytes = 0;
    config.stream = stream;
    cudaLaunchAttribute attrs[1];
    attrs[0].id = cudaLaunchAttributeClusterDimension;
    attrs[0].val.clusterDim.x = 2;
    attrs[0].val.clusterDim.y = 1;
    attrs[0].val.clusterDim.z = 1;
    config.attrs = attrs;
    config.numAttrs = 1;

    CUDA_CHECK(cudaLaunchKernelEx(&config, gemm_kernel, tma_A, tma_B, C_ptr, M, N));
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, tvm_ffi_gemm::run);

}
