__device__ __forceinline__ uint32_t pack_bf16_fn(uint32_t fp32_a, uint32_t fp32_b) {
    __nv_bfloat16 a = __float2bfloat16(__uint_as_float(fp32_a));
    __nv_bfloat16 b = __float2bfloat16(__uint_as_float(fp32_b));
    uint32_t result;
    asm("mov.b32 %0, {%1, %2};"
        : "=r"(result)
        : "h"(*reinterpret_cast<uint16_t*>(&a)),
          "h"(*reinterpret_cast<uint16_t*>(&b)));
    return result;
}

extern __shared__ uint8_t smem_base[];

__device__ __forceinline__ void get_d_coord_(int tid, int reg, int& row, int& col) {
    int t0 = tid % 4, t1 = (tid / 4) % 8, t2 = tid / 32;
    int r0 = reg % 2, r1 = (reg / 2) % 2, r2 = reg / 4;
    int lin = t0 * 128 + t1 * 1 + t2 * 16 + r0 * 64 + r1 * 8 + r2 * 512;
    row = lin % 64; col = lin / 64;
}

__global__ __launch_bounds__(128, 1) void mha_kernel(
    const __grid_constant__ CUtensorMap tma_Q,
    const __grid_constant__ CUtensorMap tma_K,
    const __grid_constant__ CUtensorMap tma_V,
    __nv_bfloat16* O_gmem,
    float* LSE_gmem,
    int S,
    int D
) {
    setmaxnreg_inc_sync_fn<256>();

    int tid = threadIdx.x;
    int bid_x = blockIdx.x;
    int bid_y = blockIdx.y;

    int start_row = bid_x * 64;
    int batch_head_offset = bid_y * S;

    __nv_bfloat16* smem_Q0 = (__nv_bfloat16*)(smem_base + 0);
    __nv_bfloat16* smem_Q1 = (__nv_bfloat16*)(smem_base + 8192);
    __nv_bfloat16* smem_K0 = (__nv_bfloat16*)(smem_base + 16384);
    __nv_bfloat16* smem_K1 = (__nv_bfloat16*)(smem_base + 24576);
    __nv_bfloat16* smem_V0 = (__nv_bfloat16*)(smem_base + 32768);
    __nv_bfloat16* smem_V1 = (__nv_bfloat16*)(smem_base + 40960);

    uint64_t* mbar_Q = (uint64_t*)(smem_base + 49152);
    uint64_t* mbar_KV = (uint64_t*)(smem_base + 49160);

    if (tid == 0) {
        init_smem_barrier_fn(mbar_Q, 1);
        init_smem_barrier_fn(mbar_KV, 1);
    }
    __syncthreads();

    if (tid == 0) {
        mbarrier_arrive_and_expect_tx_fn(mbar_Q, 16384);
        tma_load_2d_fn(&tma_Q, mbar_Q, smem_Q0, 0, batch_head_offset + start_row);
        tma_load_2d_fn(&tma_Q, mbar_Q, smem_Q1, 64, batch_head_offset + start_row);
    }
    mbarrier_wait_fn(mbar_Q, 0);

    float m_i[2] = {-1e20f, -1e20f};
    float l_i[2] = {0.0f, 0.0f};
    float acc_O0[32];
    float acc_O1[32];
    for(int i = 0; i < 32; i++) {
        acc_O0[i] = 0.0f;
        acc_O1[i] = 0.0f;
    }

    int phase = 0;
    int num_j = S / 64;
    float scale = 0.125f * 0.70710678f; // 1/sqrt(128)

    for (int j = 0; j < num_j; j++) {
        if (tid == 0) {
            mbarrier_arrive_and_expect_tx_fn(mbar_KV, 32768);
            tma_load_2d_fn(&tma_K, mbar_KV, smem_K0, 0, batch_head_offset + j * 64);
            tma_load_2d_fn(&tma_K, mbar_KV, smem_K1, 64, batch_head_offset + j * 64);
            tma_load_2d_fn(&tma_V, mbar_KV, smem_V0, 0, batch_head_offset + j * 64);
            tma_load_2d_fn(&tma_V, mbar_KV, smem_V1, 64, batch_head_offset + j * 64);
        }
        mbarrier_wait_fn(mbar_KV, phase & 1);

        float acc[32];
        for(int i = 0; i < 32; i++) acc[i] = 0.0f;

        wgmma_fence_fn();
        for (int iter = 0; iter < 4; iter++) {
            uint64_t desc_Q0 = make_wgmma_desc(smem_Q0 + iter * 16, 1, 1024, 1);
            uint64_t desc_K0 = make_wgmma_desc(smem_K0 + iter * 16, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc, desc_Q0, desc_K0);

            uint64_t desc_Q1 = make_wgmma_desc(smem_Q1 + iter * 16, 1, 1024, 1);
            uint64_t desc_K1 = make_wgmma_desc(smem_K1 + iter * 16, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc, desc_Q1, desc_K1);
        }
        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        for(int i = 0; i < 32; i++) {
            acc[i] *= scale; 
        }

        // Online Softmax Update directly from Registers to avoid additional SMEM roundtrip
        float m_curr[2] = {-1e20f, -1e20f};
        for(int i = 0; i < 32; i++) {
            int r1 = (i / 2) % 2;
            m_curr[r1] = fmaxf(m_curr[r1], acc[i]);
        }

        for (int r1 = 0; r1 < 2; r1++) {
            m_curr[r1] = fmaxf(m_curr[r1], __shfl_xor_sync(0xffffffff, m_curr[r1], 1));
            m_curr[r1] = fmaxf(m_curr[r1], __shfl_xor_sync(0xffffffff, m_curr[r1], 2));
        }

        float m_prev[2] = {m_i[0], m_i[1]};
        float m_new[2];
        for (int r1 = 0; r1 < 2; r1++) {
            m_new[r1] = fmaxf(m_prev[r1], m_curr[r1]);
        }

        for(int i = 0; i < 32; i++) {
            int r1 = (i / 2) % 2;
            float diff = m_prev[r1] - m_new[r1];
            acc_O0[i] *= expf(diff);
            acc_O1[i] *= expf(diff);
        }

        float l_curr[2] = {0.0f, 0.0f};
        for(int i = 0; i < 32; i++) {
            int r1 = (i / 2) % 2;
            float p = expf(acc[i] - m_new[r1]);
            acc[i] = p; 
            l_curr[r1] += p;
        }

        for (int r1 = 0; r1 < 2; r1++) {
            l_curr[r1] += __shfl_xor_sync(0xffffffff, l_curr[r1], 1);
            l_curr[r1] += __shfl_xor_sync(0xffffffff, l_curr[r1], 2);
        }

        for(int i = 0; i < 2; i++) {
            float l_scale = expf(m_prev[i] - m_new[i]);
            l_i[i] = l_i[i] * l_scale + l_curr[i];
            m_i[i] = m_new[i];
        }

        __syncthreads();
        fence_proxy_async_fn();

        wgmma_fence_fn();
        for (int k = 0; k < 4; k++) {
            uint32_t a0 = pack_bf16_fn(*(uint32_t*)&acc[k*8 + 0], *(uint32_t*)&acc[k*8 + 1]);
            uint32_t a1 = pack_bf16_fn(*(uint32_t*)&acc[k*8 + 2], *(uint32_t*)&acc[k*8 + 3]);
            uint32_t a2 = pack_bf16_fn(*(uint32_t*)&acc[k*8 + 4], *(uint32_t*)&acc[k*8 + 5]);
            uint32_t a3 = pack_bf16_fn(*(uint32_t*)&acc[k*8 + 6], *(uint32_t*)&acc[k*8 + 7]);

            uint64_t desc_V0 = make_wgmma_desc(smem_V0 + k * 16, 1, 1024, 1);
            wgmma_m64n64k16_rs_fn_<0>(acc_O0, a0, a1, a2, a3, desc_V0);

            uint64_t desc_V1 = make_wgmma_desc(smem_V1 + k * 16, 1, 1024, 1);
            wgmma_m64n64k16_rs_fn_<0>(acc_O1, a0, a1, a2, a3, desc_V1);
        }
        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        __syncthreads();
        phase++;
    }

    for(int i = 0; i < 32; i++) {
        int row, col;
        get_d_coord_(tid, i, row, col);
        int r1 = (i / 2) % 2;

        float val0 = acc_O0[i] / l_i[r1];
        float val1 = acc_O1[i] / l_i[r1];

        int gm = start_row + row;
        if (gm < S) {
            O_gmem[batch_head_offset * D + gm * D + col] = __float2bfloat16(val0);
            O_gmem[batch_head_offset * D + gm * D + col + 64] = __float2bfloat16(val1);
        }
    }

    if (tid % 4 == 0) {
        int t1 = (tid / 4) % 8;
        int t2 = tid / 32;
        for (int r1 = 0; r1 < 2; r1++) {
            int row = t1 + t2 * 16 + r1 * 8;
            int gm = start_row + row;
            if (gm < S) {
                LSE_gmem[batch_head_offset + gm] = m_i[r1] + logf(l_i[r1]);
            }
        }
    }
}

namespace tvm_ffi_cuda {

CUresult create_tma_2d_descriptor_2B(CUtensorMap* d, void* globalAddress, uint64_t gmem_inner_dim, uint64_t gmem_outer_dim, uint32_t smem_inner_dim, uint32_t smem_outer_dim, CUtensorMapSwizzle swizzle, CUtensorMapL2promotion l2Promotion, CUtensorMapFloatOOBfill oobFill) {
    cuuint64_t globalDim[2] = {gmem_inner_dim, gmem_outer_dim};
    cuuint64_t globalStrides[1] = {gmem_inner_dim * 2};
    cuuint32_t boxDim[2] = {smem_inner_dim, smem_outer_dim};
    cuuint32_t elementStrides[2] = {1, 1};
    return cuTensorMapEncodeTiled(
        d,
        CU_TENSOR_MAP_DATA_TYPE_BFLOAT16,
        2, 
        globalAddress,
        globalDim,
        globalStrides,
        boxDim, 
        elementStrides,
        CU_TENSOR_MAP_INTERLEAVE_NONE,
        swizzle,
        l2Promotion,
        oobFill
    );
}

void run(tvm::ffi::TensorView Q, tvm::ffi::TensorView K, tvm::ffi::TensorView V, tvm::ffi::TensorView O, tvm::ffi::TensorView LSE) {
    CUDA_CHECK(cudaSetDevice(Q.device().device_id));

    int64_t B = Q.size(0);
    int64_t H = Q.size(1);
    int64_t S = Q.size(2);
    int64_t D = Q.size(3);

    __nv_bfloat16* Q_data = static_cast<__nv_bfloat16*>(Q.data_ptr());
    __nv_bfloat16* K_data = static_cast<__nv_bfloat16*>(K.data_ptr());
    __nv_bfloat16* V_data = static_cast<__nv_bfloat16*>(V.data_ptr());
    __nv_bfloat16* O_data = static_cast<__nv_bfloat16*>(O.data_ptr());
    float* LSE_data = static_cast<float*>(LSE.data_ptr());

    CUtensorMap tma_Q, tma_K, tma_V;
    create_tma_2d_descriptor_2B(&tma_Q, Q_data, 128, B * H * S, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    create_tma_2d_descriptor_2B(&tma_K, K_data, 128, B * H * S, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    create_tma_2d_descriptor_2B(&tma_V, V_data, 128, B * H * S, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);

    dim3 grid(S / 64, B * H);
    dim3 block(128);

    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(Q.device().device_type, Q.device().device_id));

    CUDA_CHECK(cudaFuncSetAttribute(mha_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, 49280));
    mha_kernel<<<grid, block, 49280, stream>>>(tma_Q, tma_K, tma_V, O_data, LSE_data, S, D);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, tvm_ffi_cuda::run);

