        __nv_bfloat16* cur_V0 = smem_V0[stage_idx];
        __nv_bfloat16* cur_V1 = smem_V1[stage_idx];

        __nv_bfloat16* next_K0 = smem_K0[next_stage];
        __nv_bfloat16* next_K1 = smem_K1[next_stage];
        __nv_bfloat16* next_V0 = smem_V0[next_stage];
        __nv_bfloat16* next_V1 = smem_V1[next_stage];

        int next_j = j + 1;
        if (next_j + 1 < num_j) {
            if (tid == 0) {
                mbarrier_arrive_and_expect_tx_fn(mbar_next, 32768);
                tma_load_2d_fn(&tma_K, mbar_next, next_K0, 0, batch_head_offset + (next_j + 1) * 64);
                tma_load_2d_fn(&tma_K, mbar_next, next_K1, 64, batch_head_offset + (next_j + 1) * 64);
                tma_load_2d_fn(&tma_V, mbar_next, next_V0, 0, batch_head_offset + (next_j + 1) * 64);
                tma_load_2d_fn(&tma_V, mbar_next, next_V1, 64, batch_head_offset + (next_j + 1) * 64);
            }
        }

        int parity = (stage_idx == 0) ? (phase / 2) & 1 : ((phase - 1) / 2) & 1;
        mbarrier_wait_fn(mbar_curr, parity);

        float acc[32];
        for(int i = 0; i < 32; i++) acc[i] = 0.0f;

        wgmma_fence_fn();
        for (int iter = 0; iter < 4; iter++) {
            uint64_t desc_Q0 = make_wgmma_desc(smem_Q0 + iter * 16, 1, 1024, 1);
            uint64_t desc_K0 = make_wgmma_desc(cur_K0 + iter * 16, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc, desc_Q0, desc_K0);

            uint64_t desc_Q1 = make_wgmma_desc(smem_Q1 + iter * 16, 1, 1024, 1);
            uint64_t desc_K1 = make_wgmma_desc(cur_K1 + iter * 16, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc, desc_Q1, desc_K1);
        }
        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        for(int i = 0; i < 32; i++) {
            acc[i] *= scale; 
        }

        // Fast Online Softmax Update directly from Registers avoids invalid SMEM reads
        float m_curr[2] = {-1e20f, -1e20f};
        for(int i = 0; i < 32; i++) {
            int r1 = (i / 2) % 2;
            m_curr[r1] = fmaxf(m_curr[r1], acc[i]);
        }

        for (int r1 = 0; r1 < 2; r1++) {
            m_curr[r1] = fmaxf(m_curr[r1], __shfl_xor_sync(0xffffffff, m_curr[r1], 1));
            m_curr[r1] = fmaxf(m_curr[r1], __shfl_xor_sync(0xffffffff, m_curr[r1], 2));
        }

        float m_prev[2] = {m_i[0], m_i[1]};
        float m_new[2];
        for (int r1 = 0; r1 < 2; r1++) {
            m_new[r1] = fmaxf(m_prev[r1], m_curr[r1]);
        }

        for(int i = 0; i < 32; i++) {
            int r1 = (i / 2) % 2;
            float diff = m_prev[r1] - m_new[r1];
            float scale_val = fast_exp2f_fn(diff * inv_ln2);
            acc_O0[i] *= scale_val;
            acc_O1[i] *= scale_val;
        }

        float l_curr[2] = {0.0f, 0.0f};
        for(int i = 0; i < 32; i++) {
            int r1 = (i / 2) % 2;
            float p = fast_exp2f_fn((acc[i] - m_new[r1]) * inv_ln2);
            acc[i] = p; 
            l_curr[r1] += p;
        }

        for (int r1 = 0; r1 < 2; r1++) {
            l_curr[r1] += __shfl_xor_sync(0xffffffff, l_curr[r1], 1);
            l_curr[r1] += __shfl_xor_sync(0xffffffff, l_curr[r1], 2);
        }

        for(int i = 0; i < 2; i++) {
            float l_scale = fast_exp2f_fn((m_prev[i] - m_new[i]) * inv_ln2);
            l_i[i] = l_i[i] * l_scale + l_curr[i];
            m_i[i] = m_new[i];
        }

        // Utilizing ldmatrix A Fragment mapping for direct contiguous chunk translation.
        // Eliminates scalar fallbacks entirely ensuring optimal throughput
        for(int g = 0; g < 8; g++) {
            int t1 = (tid / 4) % 8;
            for(int i = 0; i < 32; i += 4) {
                int r1 = (i / 2) % 2;
                if (g != (t1 * 2 + r1)) continue;

                int row_0, col_0, row_1, col_1;
                get_d_coord_(tid, i, row_0, col_0);
                get_d_coord_(tid, i + 2, row_1, col_1);

                int span_idx_0 = col_0 / 8;
                int span_offset_0 = (row_0 % 8) ^ (span_idx_0 / 4);
                int swizzled_col_0 = span_offset_0 * 8 + (col_0 % 8);
                int byte_offset = row_0 * 128 + swizzled_col_0 * 2;

                uint32_t p_0 = pack_bf16_fn(*(uint32_t*)&acc[i], *(uint32_t*)&acc[i+1]);
                *reinterpret_cast<uint32_t*>(smem_P + byte_offset) = p_0;

                int span_idx_1 = col_1 / 8;
                int span_offset_1 = (row_1 % 8) ^ (span_idx_1 / 4);
                int swizzled_col_1 = span_offset_1 * 8 + (col_1 % 8);
                int byte_offset_1 = row_1 * 128 + swizzled_col_1 * 2;

                uint32_t p_1 = pack_bf16_fn(*(uint32_t*)&acc[i+2], *(uint32_t*)&acc[i+3]);
                *reinterpret_cast<uint32_t*>(smem_P + byte_offset_1) = p_1;
            }
        }

        __syncthreads();
        fence_proxy_async_fn();

        wgmma_fence_fn();
        for (int iter = 0; iter < 4; iter++) {
            uint64_t desc_P = make_wgmma_desc(smem_P + iter * 16, 1, 1024, 1);
            uint64_t desc_V0 = make_wgmma_desc(cur_V0 + iter * 1024, 8192, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 1>(acc_O0, desc_P, desc_V0);

            uint64_t desc_V1 = make_wgmma_desc(cur_V1 + iter * 1024, 8192, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 1>(acc_O1, desc_P, desc_V1);
        }
        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        __syncthreads(); // Critical: Synchronize to ensure all Warpgroups are completely done reading from K/V buffers before moving to the next `j`. Guarantees zero race conditions for subsequent TMA load cycles targeting recycled buffers.
        phase++;
    }

    for(int i = 0; i < 32; i += 8) {
        int row, col;
        get_d_coord_(tid, i, row, col);

        float val0_0 = acc_O0[i] / l_i[(i / 2) % 2];
        float val0_1 = acc_O0[i + 1] / l_i[((i + 1) / 2) % 2];
        float val1_0 = acc_O1[i] / l_i[(i / 2) % 2];
        float val1_1 = acc_O1[i + 1] / l_i[((i + 1) / 2) % 2];

        uint32_t p_0 = pack_bf16_fn(*(uint32_t*)&val0_0, *(uint32_t*)&val0_1);
        uint32_t p_1 = pack_bf16_fn(*(uint32_t*)&val1_0, *(uint32_t*)&val1_1);

        float val0_2 = acc_O0[i + 2] / l_i[((i + 2) / 2) % 2];
        float val0_3 = acc_O0[i + 3] / l_i[((i + 3) / 2) % 2];
        float val1_2 = acc_O1[i + 2] / l_i[((i + 2) / 2) % 2];
        float val1_3 = acc_O1[i + 3] / l_i[((i + 3) / 2) % 2];

        uint32_t p_2 = pack_bf16_fn(*(uint32_t*)&val0_2, *(uint32_t*)&val0_3);
        uint32_t p_3 = pack_bf16_fn(*(uint32_t*)&val1_2, *(uint32_t*)&val1_3);

        float4 out;
        out.x = *reinterpret_cast<float*>(&p_0);
        out.y = *reinterpret_cast<float*>(&p_1);
        out.z = *reinterpret_cast<float*>(&p_2);
        out.w = *reinterpret_cast<float*>(&p_3);

        int gm = start_row + row;
        if (gm < S) {
            *(float4*)&O_gmem[batch_head_offset * D + gm * D + col] = out;
        }
    }

    if (tid < 32) {
        int row = tid;
        int r1 = row / 8;
        int t1 = row % 8;
        int t2 = row / 16;
        row = t1 + t2 * 16;

        int gm = start_row + row;
        if (gm < S) {
            LSE_gmem[batch_head_offset + gm] = m_i[r1] + logf(l_i[r1]);
        }
    }
}

namespace tvm_ffi_cuda {

CUresult create_tma_2d_descriptor_2B(CUtensorMap* d, void* globalAddress, uint64_t gmem_inner_dim, uint64_t gmem_outer_dim, uint32_t smem_inner_dim, uint32_t smem_outer_dim, CUtensorMapSwizzle swizzle, CUtensorMapL2promotion l2Promotion, CUtensorMapFloatOOBfill oobFill) {
    cuuint64_t globalDim[2] = {gmem_inner_dim, gmem_outer_dim};
    cuuint64_t globalStrides[1] = {gmem_inner_dim * 2};
    cuuint32_t boxDim[2] = {smem_inner_dim, smem_outer_dim};
    cuuint32_t elementStrides[2] = {1, 1};
    return cuTensorMapEncodeTiled(
        d,
        CU_TENSOR_MAP_DATA_TYPE_BFLOAT16,
        2, 
        globalAddress,
        globalDim,
        globalStrides,
        boxDim, 
        elementStrides,
        CU_TENSOR_MAP_INTERLEAVE_NONE,
        swizzle,
        l2Promotion,
        oobFill
    );
}

void run(tvm::ffi::TensorView Q, tvm::ffi::TensorView K, tvm::ffi::TensorView V, tvm::ffi::TensorView O, tvm::ffi::TensorView LSE) {
    CUDA_CHECK(cudaSetDevice(Q.device().device_id));

    int64_t B = Q.size(0);
    int64_t H = Q.size(1);
    int64_t S = Q.size(2);
    int64_t D = Q.size(3);

    __nv_bfloat16* Q_data = static_cast<__nv_bfloat16*>(Q.data_ptr());
    __nv_bfloat16* K_data = static_cast<__nv_bfloat16*>(K.data_ptr());
    __nv_bfloat16* V_data = static_cast<__nv_bfloat16*>(V.data_ptr());
    __nv_bfloat16* O_data = static_cast<__nv_bfloat16*>(O.data_ptr());
    float* LSE_data = static_cast<float*>(LSE.data_ptr());

    CUtensorMap tma_Q, tma_K, tma_V;
    create_tma_2d_descriptor_2B(&tma_Q, Q_data, 128, B * H * S, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    create_tma_2d_descriptor_2B(&tma_K, K_data, 128, B * H * S, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    create_tma_2d_descriptor_2B(&tma_V, V_data, 128, B * H * S, 64, 64, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);

    dim3 grid(S / 64, B * H);
    dim3 block(128);

    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(Q.device().device_type, Q.device().device_id));

    CUDA_CHECK(cudaFuncSetAttribute(mha_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, 98368));
    mha_kernel<<<grid, block, 98368, stream>>>(tma_Q, tma_K, tma_V, O_data, LSE_data, S, D);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, tvm_ffi_cuda::run);

