__device__ __forceinline__ void init_smem_barrier_fn(uint64_t* bar, uint32_t count) {
    asm volatile("mbarrier.init.shared.b64 [%0], %1;"
        :: "r"((uint32_t)__cvta_generic_to_shared(&bar[0])), "r"(count));
}

__device__ __forceinline__ void mbarrier_arrive_and_expect_tx_fn(uint64_t* bar, uint32_t tx_bytes) {
    asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;"
        :: "r"((uint32_t)__cvta_generic_to_shared(&bar[0])), "r"(tx_bytes) : "memory");
}

__device__ __forceinline__ void mbarrier_wait_fn(uint64_t* bar, uint32_t phase) {
    asm volatile(
        "{\n"
        ".reg .pred P;\n"
        "WAIT_%=:\n"
        "mbarrier.try_wait.parity.shared.b64 P, [%0], %1;\n"
        "@!P bra WAIT_%=;\n"
        "}\n"
        :: "r"((uint32_t)__cvta_generic_to_shared(&bar[0])), "r"(phase));
}

__device__ __forceinline__ void tma_load_3d_fn(const CUtensorMap* d, uint64_t* bar, void* smem, int32_t c0, int32_t c1, int32_t c2) {
    asm volatile(
        "cp.async.bulk.tensor.3d.shared::cta.global.mbarrier::complete_tx::bytes [%0], [%1, {%3, %4, %5}], [%2];"
        :: "r"((uint32_t)__cvta_generic_to_shared(smem)),
        "l"((uint64_t)d),
        "r"((uint32_t)__cvta_generic_to_shared(&bar[0])),
        "r"(c0), "r"(c1), "r"(c2) : "memory");
}

__device__ __forceinline__ void named_barrier_sync_fn(int bar_id, int count) {
    asm volatile("barrier.sync.aligned %0, %1;" :: "r"(bar_id), "r"(count));
}

extern __shared__ char smem_pool[];

__global__ void __launch_bounds__(256, 2)
attention_kernel(
    const __grid_constant__ CUtensorMap tma_q,
    const __grid_constant__ CUtensorMap tma_k,
    const __grid_constant__ CUtensorMap tma_v,
    __nv_bfloat16* O_global,
    float* LSE_global,
    int B, int H, int S, int D,
    float scale)
{
    setmaxnreg_inc_sync_fn<248>();

    int tid = threadIdx.x; 
    int bx = blockIdx.x; 
    int by = blockIdx.y; 
    int b_h = by;
    int q_offset = bx * 64;
    int wg_id = tid / 128;

    // Explicitly Shifted Offset Scaling (x2 Scaling Constants Emulated): 
    // Each 64x64 Tile occupies precisely 8192 bytes in physical memory
    __nv_bfloat16* smem_Q0 = (__nv_bfloat16*)(smem_pool);                             // 0
    __nv_bfloat16* smem_Q1 = (__nv_bfloat16*)(smem_pool + 8192);                       // 8192

    // Pipelined Staging for complete concurrency overlap
    __nv_bfloat16* smem_K0_0 = (__nv_bfloat16*)(smem_pool + 16384);                    // 16384
    __nv_bfloat16* smem_K1_0 = (__nv_bfloat16*)(smem_pool + 24576);                    // 24576
    __nv_bfloat16* smem_V0_0 = (__nv_bfloat16*)(smem_pool + 32768);                    // 32768
    __nv_bfloat16* smem_V1_0 = (__nv_bfloat16*)(smem_pool + 40960);                    // 40960

    __nv_bfloat16* smem_K0_1 = (__nv_bfloat16*)(smem_pool + 49152);                    // 49152
    __nv_bfloat16* smem_K1_1 = (__nv_bfloat16*)(smem_pool + 57344);                    // 57344
    __nv_bfloat16* smem_V0_1 = (__nv_bfloat16*)(smem_pool + 65536);                    // 65536
    __nv_bfloat16* smem_V1_1 = (__nv_bfloat16*)(smem_pool + 73728);                    // 73728

    __nv_bfloat16* smem_K0[2] = {smem_K0_0, smem_K0_1};
    __nv_bfloat16* smem_K1[2] = {smem_K1_0, smem_K1_1};
    __nv_bfloat16* smem_V0[2] = {smem_V0_0, smem_V0_1};
    __nv_bfloat16* smem_V1[2] = {smem_V1_0, smem_V1_1};

    uint64_t* bar_Q = (uint64_t*)(smem_pool + 81920);        // 81920
    uint64_t* bar_KV_0 = (uint64_t*)(smem_pool + 81928);     // 81928
    uint64_t* bar_KV_1 = (uint64_t*)(smem_pool + 81936);     // 81936
    uint64_t* bar_KV[2] = {bar_KV_0, bar_KV_1};

    if (tid == 0) {
        init_smem_barrier_fn(bar_Q, 1);
        init_smem_barrier_fn(bar_KV[0], 1);
        init_smem_barrier_fn(bar_KV[1], 1);
    }
    __syncthreads();

    if (tid == 0) {
        mbarrier_arrive_and_expect_tx_fn(bar_Q, 16384);
        tma_load_3d_fn(&tma_q, bar_Q, smem_Q0, 0, q_offset, b_h);
        tma_load_3d_fn(&tma_q, bar_Q, smem_Q1, 64, q_offset, b_h);
    }

    mbarrier_wait_fn(bar_Q, 0);
    __syncthreads();

    int num_stages = (S + 63) / 64;

    if (tid == 0 && 0 < num_stages) {
        mbarrier_arrive_and_expect_tx_fn(bar_KV[0], 32768);
        tma_load_3d_fn(&tma_k, bar_KV[0], smem_K0[0], 0, 0, b_h);
        tma_load_3d_fn(&tma_k, bar_KV[0], smem_K1[0], 64, 0, b_h);
        tma_load_3d_fn(&tma_v, bar_KV[0], smem_V0[0], 0, 0, b_h);
        tma_load_3d_fn(&tma_v, bar_KV[0], smem_V1[0], 64, 0, b_h);
    }

    float acc_O0[32];
    float acc_O1[32];
    for(int i=0; i<32; ++i) { acc_O0[i] = 0.0f; acc_O1[i] = 0.0f; }

    float r_m[2] = {-INFINITY, -INFINITY};
    float r_l_sum[2] = {0.0f, 0.0f};

    for (int j = 0; j < num_stages; ++j) {
        int s = j % 2;
        int next_s = (j + 1) % 2;
        int next_kv_offset = (j + 1) * 64;

        int phase_k = (j / 2) % 2;
        mbarrier_wait_fn(bar_KV[s], phase_k);

        if (tid == 0 && (j + 1) < num_stages) {
            mbarrier_arrive_and_expect_tx_fn(bar_KV[next_s], 32768);
            tma_load_3d_fn(&tma_k, bar_KV[next_s], smem_K0[next_s], 0, next_kv_offset, b_h);
            tma_load_3d_fn(&tma_k, bar_KV[next_s], smem_K1[next_s], 64, next_kv_offset, b_h);
            tma_load_3d_fn(&tma_v, bar_KV[next_s], smem_V0[next_s], 0, next_kv_offset, b_h);
            tma_load_3d_fn(&tma_v, bar_KV[next_s], smem_V1[next_s], 64, next_kv_offset, b_h);
        }

        float acc_S[32];
        for(int i=0; i<32; ++i) acc_S[i] = 0.0f;

        wgmma_fence_fn();
        #pragma unroll
        for(int k=0; k<64; k+=16) {
            uint64_t d_q0 = make_wgmma_desc_bytes((uint8_t*)smem_Q0 + k * 2, 1, 1024, 1);
            uint64_t d_k0 = make_wgmma_desc_bytes((uint8_t*)smem_K0[s] + k * 2, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc_S, d_q0, d_k0);

            uint64_t d_q1 = make_wgmma_desc_bytes((uint8_t*)smem_Q1 + k * 2, 1, 1024, 1);
            uint64_t d_k1 = make_wgmma_desc_bytes((uint8_t*)smem_K1[s] + k * 2, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc_S, d_q1, d_k1);
        }

        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        named_barrier_sync_fn(1 + wg_id, 128);

        float local_max[2] = {-INFINITY, -INFINITY};
        #pragma unroll
        for(int r=0; r<32; ++r) {
            int lm, ln;
            get_d_coord_(tid, r, lm, ln);
            acc_S[r] *= scale;
            int r1 = (r / 2) % 2;
            local_max[r1] = fmaxf(local_max[r1], acc_S[r]);
        }

        #pragma unroll
        for(int xor_val=1; xor_val<=3; xor_val+=2) {
            local_max[0] = fmaxf(local_max[0], __shfl_xor_sync(0xffffffff, local_max[0], xor_val));
            local_max[1] = fmaxf(local_max[1], __shfl_xor_sync(0xffffffff, local_max[1], xor_val));
        }

        float new_max[2];
        new_max[0] = fmaxf(r_m[0], local_max[0]);
        new_max[1] = fmaxf(r_m[1], local_max[1]);

        float exp_old[2];
        exp_old[0] expf(r_m[0] - new_max[0]);
        exp_old[1] expf(r_m[1] - new_max[1]);

        float local_sum[2] = {0.0f, 0.0f};
        #pragma unroll
        for(int r=0; r<32; ++r) {
            int r1 = (r / 2) % 2;
            acc_S[r] = expf(acc_S[r] - new_max[r1]);
            local_sum[r1] += acc_S[r];
        }

        #pragma unroll
        for(int xor_val=1; xor_val<=3; xor_val+=2) {
            local_sum[0] += __shfl_xor_sync(0xffffffff, local_sum[0], xor_val);
            local_sum[1] += __shfl_xor_sync(0xffffffff, local_sum[1], xor_val);
        }

        r_l_sum[0] = r_l_sum[0] * exp_old[0] + local_sum[0];
        r_l_sum[1] = r_l_sum[1] * exp_old[1] + local_sum[1];
        r_m[0] = new_max[0];
        r_m[1] = new_max[1];

        #pragma unroll
        for(int r=0; r<32; ++r) {
            int r1 = (r / 2) % 2;
            acc_O0[r] *= exp_old[r1];
            acc_O1[r] *= exp_old[r1];
        }

        named_barrier_sync_fn(3 + wg_id, 128);
        named_barrier_sync_fn(1 + wg_id, 128);

        wgmma_fence_fn();
        #pragma unroll
        for(int k=0; k<64; k+=16) {
            int i = k / 16;
            __nv_bfloat162 p_bf0 = __floats2bfloat162_rn(acc_S[i*8 + 0], acc_S[i*8 + 1]);
            __nv_bfloat162 p_bf1 = __floats2bfloat162_rn(acc_S[i*8 + 2], acc_S[i*8 + 3]);
            __nv_bfloat162 p_bf2 = __floats2bfloat162_rn(acc_S[i*8 + 4], acc_S[i*8 + 5]);
            __nv_bfloat162 p_bf3 = __floats2bfloat162_rn(acc_S[i*8 + 6], acc_S[i*8 + 7]);

            uint32_t a0 = *(uint32_t*)&p_bf0;
            uint32_t a1 = *(uint32_t*)&p_bf1;
            uint32_t a2 = *(uint32_t*)&p_bf2;
            uint32_t a3 = *(uint32_t*)&p_bf3;

            uint64_t d_v0 = make_wgmma_desc_bytes((uint8_t*)smem_V0[s] + k * 128, 1024, 1024, 1);
            wgmma_m64n64k16_rs_fn_<1>(acc_O0, a0, a1, a2, a3, d_v0);

            uint64_t d_v1 = make_wgmma_desc_bytes((uint8_t*)smem_V1[s] + k * 128, 1024, 1024, 1);
            wgmma_m64n64k16_rs_fn_<1>(acc_O1, a0, a1, a2, a3, d_v1);
        }

        wgmma_commit_fn();
        wgmma_wait_fn<0>();
        named_barrier_sync_fn(4 + wg_id, 128);
        __syncthreads();
    }

    #pragma unroll
    for(int r=0; r<32; ++r) {
        int lm, ln;
        get_d_coord_(tid, r, lm, ln);
        int r1 = (r / 2) % 2;
        float inv_l = 1.0f / r_l_sum[r1];
        acc_O0[r] *= inv_l;
        acc_O1[r] *= inv_l;
    }

    if (wg_id == 0) {
        __nv_bfloat16* C = O_global + b_h * S * D;
        #pragma unroll
        for(int r=0; r<32; ++r) {
            int lm, ln;
            get_d_coord_(tid, r, lm, ln);
            int gm = q_offset + lm;
            if (gm < S) {
                C[gm * D + ln] = __float2bfloat16(acc_O0[r]);
                C[gm * D + 64 + ln] = __float2bfloat16(acc_O1[r]);
            }
        }

        int t0_local = tid % 4;
        if (t0_local == 0) {
            int t1 = (tid / 4) % 8;
            int t2 = tid / 32;
            int row0 = t1 + t2 * 16;
            int row1 = row0 + 8;

            int gm0 = q_offset + row0;
            if (gm0 < S) {
                LSE_global[b_h * S + gm0] = r_m[0] + logf(r_l_sum[0]);
            }
            int gm1 = q_offset + row1;
            if (gm1 < S) {
                LSE_global[b_h * S + gm1] = r_m[1] + logf(r_l_sum[1]);
            }
        }
    }
}

void run(tvm::ffi::TensorView Q, tvm::ffi::TensorView K, tvm::ffi::TensorView V, tvm::ffi::TensorView O, tvm::ffi::TensorView LSE) {
    CUDA_CHECK(cudaSetDevice(Q.device().device_id));
    int64_t B = Q.size(0);
    int64_t H = Q.size(1);
    int64_t S = Q.size(2);
    int64_t D = Q.size(3);

    __nv_bfloat16* Q_ptr = static_cast<__nv_bfloat16*>(Q.data_ptr());
    __nv_bfloat16* K_ptr = static_cast<__nv_bfloat16*>(K.data_ptr());
    __nv_bfloat16* V_ptr = static_cast<__nv_bfloat16*>(V.data_ptr());
    __nv_bfloat16* O_ptr = static_cast<__nv_bfloat16*>(O.data_ptr());
    float*         LSE_ptr = static_cast<float*>(LSE.data_ptr());

    cuuint64_t globalDim_Q[3] = {(cuuint64_t)D, (cuuint64_t)S, (cuuint64_t)(B * H)};
    cuuint64_t globalStrides_Q[2] = {(cuuint64_t)(D * sizeof(__nv_bfloat16)), (cuuint64_t)(S * D * sizeof(__nv_bfloat16))};
    cuuint32_t boxDim_Q[3] = {64, 64, 1};
    cuuint32_t elementStrides_Q[3] = {1, 1, 1};

    CUtensorMap tma_q, tma_k, tma_v;
    auto res = cuTensorMapEncodeTiled(&tma_q, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 3, Q_ptr,
        globalDim_Q, globalStrides_Q, boxDim_Q, elementStrides_Q, CU_TENSOR_MAP_INTERLEAVE_NONE,
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    if(res != CUDA_SUCCESS) { fprintf(stderr, "cuTensorMapEncodeTiled Q failed\n"); exit(1); }

    res = cuTensorMapEncodeTiled(&tma_k, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 3, K_ptr,
        globalDim_Q, globalStrides_Q, boxDim_Q, elementStrides_Q, CU_TENSOR_MAP_INTERLEAVE_NONE,
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    if(res != CUDA_SUCCESS) { fprintf(stderr, "cuTensorMapEncodeTiled K failed\n"); exit(1); }

    res = cuTensorMapEncodeTiled(&tma_v, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 3, V_ptr,
        globalDim_Q, globalStrides_Q, boxDim_Q, elementStrides_Q, CU_TENSOR_MAP_INTERLEAVE_NONE,
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    if(res != CUDA_SUCCESS) { fprintf(stderr, "cuTensorMapEncodeTiled V failed\n"); exit(1); }

    int smem_bytes = 81920 + 24; // Up to 90112 bytes requested dynamically
    cudaFuncSetAttribute(attention_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_bytes);

    dim3 grid((S + 63) / 64, B * H);
    dim3 block(256); // Utilize robust parallel Warpgroup configurations 
    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(Q.device().device_type, Q.device().device_id));

    float scale = 1.0f / sqrtf((float)D);

    attention_kernel<<<grid, block, smem_bytes, stream>>>(
        tma_q, tma_k, tma_v, O_ptr, LSE_ptr,
        B, H, S, D, scale
    );
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

