        "{%32,%33,%34,%35}, %36, p, 1, 1, %37;\n}\n"
        : "+f"(c[0]),"+f"(c[1]),"+f"(c[2]),"+f"(c[3]),"+f"(c[4]),"+f"(c[5]),"+f"(c[6]),"+f"(c[7]),
          "+f"(c[8]),"+f"(c[9]),"+f"(c[10]),"+f"(c[11]),"+f"(c[12]),"+f"(c[13]),"+f"(c[14]),"+f"(c[15]),
          "+f"(c[16]),"+f"(c[17]),"+f"(c[18]),"+f"(c[19]),"+f"(c[20]),"+f"(c[21]),"+f"(c[22]),"+f"(c[23]),
          "+f"(c[24]),"+f"(c[25]),"+f"(c[26]),"+f"(c[27]),"+f"(c[28]),"+f"(c[29]),"+f"(c[30]),"+f"(c[31])
        : "r"(a0), "r"(a1), "r"(a2), "r"(a3), "l"(db), "n"(trans_b));
}

__device__ __forceinline__ void get_d_coord_(int tid, int reg, int& row, int& col) {
    int t0 = tid % 4, t1 = (tid / 4) % 8, t2 = tid / 32;
    int r0 = reg % 2, r1 = (reg / 2) % 2, r2 = reg / 4;
    int lin = t0 * 128 + t1 * 1 + t2 * 16 + r0 * 64 + r1 * 8 + r2 * 512;
    row = lin % 64; col = lin / 64;
}

__device__ __forceinline__ void named_barrier_sync_fn(int bar_id, int count) {
    asm volatile("barrier.sync.aligned %0, %1;" :: "r"(bar_id), "r"(count));
}

__device__ __forceinline__ void fence_proxy_async_fn() {
    asm volatile("fence.proxy.async;\n" ::: "memory");
}

__device__ __forceinline__ uint32_t pack_bf16_fn(uint32_t fp32_a, uint32_t fp32_b) {
    __nv_bfloat16 a = __float2bfloat16(__uint_as_float(fp32_a));
    __nv_bfloat16 b = __float2bfloat16(__uint_as_float(fp32_b));
    uint32_t result;
    asm("mov.b32 %0, {%1, %2};"
        : "=r"(result)
        : "h"(*reinterpret_cast<uint16_t*>(&a)),
          "h"(*reinterpret_cast<uint16_t*>(&b)));
    return result;
}

__device__ __forceinline__ void store_acc_to_smem_64x64_swizzle(__nv_bfloat16* smem, const float* acc, int tid) {
    #pragma unroll
    for (int i = 0; i < 32; i++) {
        int row, col;
        get_d_coord_(tid, i, row, col);
        int swizzled_col = col ^ ((row % 8) * 8);
        smem[row * 64 + swizzled_col] = __float2bfloat16(acc[i]);
    }
}

namespace tvm_ffi_cuda {

CUresult create_tma_2d_descriptor_2B(CUtensorMap* d, void* globalAddress, uint64_t gmem_inner_dim, uint64_t gmem_outer_dim, uint32_t smem_inner_dim, uint32_t smem_outer_dim, CUtensorMapSwizzle swizzle, CUtensorMapL2promotion l2Promotion, CUtensorMapFloatOOBfill oobFill) {
    cuuint64_t globalDim[2] = {gmem_inner_dim, gmem_outer_dim};
    cuuint64_t globalStrides[1] = {gmem_inner_dim * 2};
    cuuint32_t boxDim[2] = {smem_inner_dim, smem_outer_dim};
    cuuint32_t elementStrides[2] = {1, 1};
    return cuTensorMapEncodeTiled(
        d,
        CU_TENSOR_MAP_DATA_TYPE_BFLOAT16,
        2, 
        globalAddress,
        globalDim,
        globalStrides,
        boxDim, 
        elementStrides,
        CU_TENSOR_MAP_INTERLEAVE_NONE,
        swizzle,
        l2Promotion,
        oobFill
    );
}

__global__ void __launch_bounds__(128, 1) causal_mha_kernel(
    const __grid_constant__ CUtensorMap tma_Q,
    const __grid_constant__ CUtensorMap tma_K,
    const __grid_constant__ CUtensorMap tma_V,
    __nv_bfloat16* __restrict__ O_gptr,
    float* __restrict__ LSE_gptr,
    int S, int H, int B, int D
) {
    setmaxnreg_inc_sync_fn_248();

    int b = blockIdx.z;
    int h = blockIdx.y;
    int s_q = blockIdx.x;
    int tid = threadIdx.x;

    __shared__ __align__(128) uint8_t smem_pool[57360 + 16];
    __nv_bfloat16* sm_Q0 = (__nv_bfloat16*)(smem_pool + 0);        
    __nv_bfloat16* sm_Q1 = (__nv_bfloat16*)(smem_pool + 8192);      
    __nv_bfloat16* sm_K0 = (__nv_bfloat16*)(smem_pool + 16384);     
    __nv_bfloat16* sm_K1 = (__nv_bfloat16*)(smem_pool + 24576);     
    __nv_bfloat16* sm_V0 = (__nv_bfloat16*)(smem_pool + 32768);     
    __nv_bfloat16* sm_V1 = (__nv_bfloat16*)(smem_pool + 40960);     
    __nv_bfloat16* sm_P  = (__nv_bfloat16*)(smem_pool + 49152);     

    __shared__ alignas(8) uint64_t bar_Q[1];
    __shared__ alignas(8) uint64_t bar_K[1];
    __shared__ alignas(8) uint64_t bar_V[1];

    if (tid == 0) {
        init_smem_barrier_fn(bar_Q, 1);
        init_smem_barrier_fn(bar_K, 1);
        init_smem_barrier_fn(bar_V, 1);
    }
    fence_smem_barrier_init_fn();
    __syncthreads();

    float acc_0[32];
    float acc_1[32];
    for(int i=0; i<32; i++) { acc_0[i] = 0.0f; acc_1[i] = 0.0f; }

    float m_global[2] = {-INFINITY, -INFINITY};
    float l_global[2] = {0.0f, 0.0f};

    int num_blocks_s = (S + 63) / 64;
    float sqrt_d = sqrtf((float)D);

    int32_t coord1_Q = b * H * S + h * S + s_q * 64;

    if (tid == 0) {
        mbarrier_arrive_and_expect_tx_fn(bar_Q, 16384);
        tma_load_2d_fn(&tma_Q, bar_Q, sm_Q0, 0, coord1_Q);
        tma_load_2d_fn(&tma_Q, bar_Q, sm_Q1, 64, coord1_Q);
    }
    mbarrier_wait_fn(bar_Q, 0);
    int bar_phase_K = 0;
    int bar_phase_V = 0;

    for (int s_k = 0; s_k <= s_q && s_k < num_blocks_s; s_k++) {
        int32_t coord1_K = b * H * S + h * S + s_k * 64;
        int32_t coord1_V = b * H * S + h * S + s_k * 64;

        if (tid == 0) {
            mbarrier_arrive_and_expect_tx_fn(bar_K, 16384);
            tma_load_2d_fn(&tma_K, bar_K, sm_K0, 0, coord1_K);
            tma_load_2d_fn(&tma_K, bar_K, sm_K1, 64, coord1_K);

            mbarrier_arrive_and_expect_tx_fn(bar_V, 16384);
            tma_load_2d_fn(&tma_V, bar_V, sm_V0, 0, coord1_V);
            tma_load_2d_fn(&tma_V, bar_V, sm_V1, 64, coord1_V);
        }

        mbarrier_wait_fn(bar_K, bar_phase_K);
        bar_phase_K ^= 1;

        fence_proxy_async_fn();
        wgmma_fence_fn();

        float acc[32];
        for(int i=0; i<32; i++) acc[i] = 0.0f;
        wgmma_fence_operand_array_fn(acc, 32);

        #pragma unroll
        for(int k=0; k<64; k+=16) {
            uint64_t desc_A = make_wgmma_desc(sm_Q0 + k, 1, 1024, 1);
            uint64_t desc_B = make_wgmma_desc(sm_K0 + k, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0,0>(acc, desc_A, desc_B);
        }
        #pragma unroll
        for(int k=0; k<64; k+=16) {
            uint64_t desc_A = make_wgmma_desc(sm_Q1 + k, 1, 1024, 1);
            uint64_t desc_B = make_wgmma_desc(sm_K1 + k, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0,0>(acc, desc_A, desc_B);
        }

        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        float m_buf[2] = {-INFINITY, -INFINITY};
        #pragma unroll
        for(int i=0; i<32; i++) {
            int r1 = (i/2) % 2;
            int lm, ln;
            get_d_coord_(tid, i, lm, ln);
            int r = lm;
            int c = ln;

            int q_idx = s_q * 64 + r;
            int c_idx = s_k * 64 + c;

            if (q_idx >= S && c_idx < S) {
                acc[i] = -INFINITY;
            } else if (c_idx > q_idx || c_idx >= S) {
                acc[i] = -INFINITY;
            } else {
                acc[i] /= sqrt_d;
            }
            m_buf[r1] = fmaxf(m_buf[r1], acc[i]);
        }

        #pragma unroll
        for(int r1=0; r1<2; r1++) {
            m_buf[r1] = fmaxf(m_buf[r1], __shfl_xor_sync(0xffffffff, m_buf[r1], 1));
            m_buf[r1] = fmaxf(m_buf[r1], __shfl_xor_sync(0xffffffff, m_buf[r1], 2));
        }

        float m_new[2];
        #pragma unroll
        for(int r1=0; r1<2; r1++) {
            m_new[r1] = fmaxf(m_global[r1], m_buf[r1]);
        }

        float l_buf[2] = {0.0f, 0.0f};
        #pragma unroll
        for(int i=0; i<32; i++) {
            int r1 = (i/2) % 2;
            acc[i] = expf(acc[i] - m_new[r1]);
            l_buf[r1] += acc[i];
        }

        #pragma unroll
        for(int r1=0; r1<2; r1++) {
            l_buf[r1] += __shfl_xor_sync(0xffffffff, l_buf[r1], 1);
            l_buf[r1] += __shfl_xor_sync(0xffffffff, l_buf[r1], 2);
        }

        float l_prev[2];
        float m_old_val[2];
        #pragma unroll
        for(int r1=0; r1<2; r1++) {
            m_old_val[r1] = m_global[r1];
            l_prev[r1] = (m_old_val[r1] == -INFINITY) ? 0.0f : l_global[r1] * expf(m_old_val[r1] - m_new[r1]);
            l_global[r1] = l_prev[r1] + l_buf[r1];
            m_global[r1] = m_new[r1];
        }

        #pragma unroll
        for(int i=0; i<32; i++) {
            int r1 = (i/2) % 2;
            if (m_old_val[r1] == -INFINITY) {
                // do nothing to acc_0 and acc_1 as they are 0
            } else {
                float scale = expf(m_old_val[r1] - m_global[r1]);
                acc_0[i] *= scale;
                acc_1[i] *= scale;
            }
        }

        wgmma_fence_operand_array_fn(acc_0, 32);
        wgmma_fence_operand_array_fn(acc_1, 32);

        store_acc_to_smem_64x64_swizzle(sm_P, acc, tid);

        mbarrier_wait_fn(bar_V, bar_phase_V);
        bar_phase_V ^= 1;

        named_barrier_sync_fn(1, 128); 
        fence_proxy_async_fn();
        wgmma_fence_fn();

        #pragma unroll
        for(int k=0; k<64; k+=16) {
            uint64_t desc_A = make_wgmma_desc(sm_P + k, 1, 1024, 1);

            uint64_t desc_B0 = make_wgmma_desc(sm_V0 + k, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0,0>(acc_0, desc_A, desc_B0);

            uint64_t desc_B1 = make_wgmma_desc(sm_V1 + k, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0,0>(acc_1, desc_A, desc_B1);
        }

        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        named_barrier_sync_fn(1, 128);
    }

    int64_t b_h_offset = (b * H + h) * S * D;
    #pragma unroll
    for(int i=0; i<32; i++) {
        int r1 = (i/2) % 2, r2 = i/4, r0 = i%2;
        int row = ((tid/4) % 8) + (tid/32) * 16 + r1 * 8;
        int col = (tid%4)*2 + r0 + r2*8;

        float inv_l = (l_global[r1] > 0.0f) ? (1.0f / l_global[r1]) : 0.0f;

        float o_val0 = acc_0[i] * inv_l;
        float o_val1 = acc_1[i] * inv_l;

        int global_row = s_q * 64 + row;
        if (global_row < S) {
            O_gptr[b_h_offset + global_row * 128 + col] = __float2bfloat16(o_val0);
            O_gptr[b_h_offset + global_row * 128 + col + 64] = __float2bfloat16(o_val1);
        }
    }

    if (tid % 4 == 0) {
        #pragma unroll
        for(int r1=0; r1<2; r1++) {
            int row = ((tid/4) % 8) + (tid/32) * 16 + r1 * 8;
            int global_row = s_q * 64 + row;
            if (global_row < S) {
                float m = m_global[r1];
                float l = l_global[r1];
                float lse = (l > 0.0f) ? (m + logf(l)) : -INFINITY;
                LSE_gptr[(b * H + h) * S + global_row] = lse;
            }
        }
    }
}

void run(tvm::ffi::TensorView Q, tvm::ffi::TensorView K, tvm::ffi::TensorView V, tvm::ffi::TensorView O, tvm::ffi::TensorView LSE) {
    CUDA_CHECK(cudaSetDevice(Q.device().device_id));

    int64_t B = Q.size(0);
    int64_t H = Q.size(1);
    int64_t S = Q.size(2);
    int64_t D = Q.size(3);

    CUtensorMap tma_Q, tma_K, tma_V;

    if (create_tma_2d_descriptor_2B(&tma_Q, Q.data_ptr(), D, B * H * S, 64, 64, 
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
        fprintf(stderr, "Failed to create TMA descriptor for Q\n");
        exit(1);
    }
    if (create_tma_2d_descriptor_2B(&tma_K, K.data_ptr(), D, B * H * S, 64, 64, 
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
        fprintf(stderr, "Failed to create TMA descriptor for K\n");
        exit(1);
    }
    if (create_tma_2d_descriptor_2B(&tma_V, V.data_ptr(), D, B * H * S, 64, 64, 
        CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
        fprintf(stderr, "Failed to create TMA descriptor for V\n");
        exit(1);
    }

    dim3 grid((S + 63) / 64, H, B);
    dim3 block(128);

    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(Q.device().device_type, Q.device().device_id));

    cudaFuncSetAttribute(causal_mha_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, 57376);

    causal_mha_kernel<<<grid, block, 57376, stream>>>(
        tma_Q, tma_K, tma_V, 
        static_cast<__nv_bfloat16*>(O.data_ptr()), 
        static_cast<float*>(LSE.data_ptr()), 
        S, H, B, D
    );
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, run);

