          "+f"(c[8]),"+f"(c[9]),"+f"(c[10]),"+f"(c[11]),"+f"(c[12]),"+f"(c[13]),"+f"(c[14]),"+f"(c[15]),
          "+f"(c[16]),"+f"(c[17]),"+f"(c[18]),"+f"(c[19]),"+f"(c[20]),"+f"(c[21]),"+f"(c[22]),"+f"(c[23]),
          "+f"(c[24]),"+f"(c[25]),"+f"(c[26]),"+f"(c[27]),"+f"(c[28]),"+f"(c[29]),"+f"(c[30]),"+f"(c[31])
        : "l"(da), "l"(db), "n"(trans_a), "n"(trans_b));
}

__device__ __forceinline__ void get_d_coord_(int tid, int reg, int& row, int& col) {
    int t0 = tid % 4, t1 = (tid / 4) % 8, t2 = tid / 32;
    int r0 = reg % 2, r1 = (reg / 2) % 2, r2 = reg / 4;
    int lin = t0 * 128 + t1 * 1 + t2 * 16 + r0 * 64 + r1 * 8 + r2 * 512;
    row = lin % 64; col = lin / 64;
}

__device__ __forceinline__ float fast_exp2f_fn(float x) {
    float y;
    asm volatile("ex2.approx.ftz.f32 %0, %1;" : "=f"(y) : "f"(x));
}

__device__ __forceinline__ void store_acc_smem_64x64_swizzle(__nv_bfloat16* smem, float* acc, int tid) {
    #pragma unroll
    for (int r = 0; r < 32; r++) {
        int row, col;
        get_d_coord_(tid, r, row, col);
        int x_chunk = col / 8;
        int swizzled_x_chunk = x_chunk ^ (row % 8);
        int swizzled_col = swizzled_x_chunk * 8 + (col % 8);
        smem[row * 64 + swizzled_col] = __float2bfloat16(acc[r]);
    }
}

__device__ __forceinline__ void store_acc_global_n128_fn(
    __nv_bfloat16* C, float* ac, int bm, int bn, int B, int H, int S, int D, int tid, int bh_idx) {
    #pragma unroll
    for (int r = 0; r < 32; r++) {
        int lm, ln;
        get_d_coord_(tid, r, lm, ln);
        int gm = bm + lm, gn = bn + ln;
        if (gm < S && gn < D) {
            C[(int64_t)((bh_idx * S + gm) * D + gn)] = __float2bfloat16(ac[r]);
        }
    }
}

CUresult create_tma_3d_descriptor_2B(CUtensorMap* d, void* globalAddress, 
                                     uint64_t gmem_dim0, uint64_t gmem_dim1, uint64_t gmem_dim2,
                                     uint32_t smem_dim0, uint32_t smem_dim1, uint32_t smem_dim2,
                                     CUtensorMapSwizzle swizzle, CUtensorMapL2promotion l2Promotion, CUtensorMapFloatOOBfill oobFill) {
    cuuint64_t globalDim[3] = {gmem_dim0, gmem_dim1, gmem_dim2};
    cuuint64_t globalStrides[2] = {gmem_dim0 * 2, gmem_dim0 * gmem_dim1 * 2};
    cuuint32_t boxDim[3] = {smem_dim0, smem_dim1, smem_dim2};
    cuuint32_t elementStrides[3] = {1, 1, 1};
    return cuTensorMapEncodeTiled(
        d, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 3, globalAddress, globalDim, globalStrides,
        boxDim, elementStrides, CU_TENSOR_MAP_INTERLEAVE_NONE, swizzle, l2Promotion, oobFill
    );
}

__global__ void __launch_bounds__(128, 2) causal_mha_fwd(
    const __grid_constant__ CUtensorMap tma_Q,
    const __grid_constant__ CUtensorMap tma_K,
    const __grid_constant__ CUtensorMap tma_V,
    __nv_bfloat16* O_ptr,
    float* LSE_ptr,
    int S, int B, int H, int D
) {
    int bid_y = blockIdx.y;
    int bid_z = blockIdx.z;
    int bh_idx = bid_y + bid_z * gridDim.y;
    int base_row = blockIdx.x * 128;

    if (base_row >= S) return;

    extern __shared__ __align__(128) __nv_bfloat16 smem_pool[];
    uintptr_t smem_base = reinterpret_cast<uintptr_t>(smem_pool);
    int alignment_padding = (1024 - (smem_base % 1024)) % 1024;
    uintptr_t aligned_smem_base = smem_base + alignment_padding;

    __nv_bfloat16* smem_Q0 = reinterpret_cast<__nv_bfloat16*>(aligned_smem_base);
    __nv_bfloat16* smem_Q1 = smem_Q0 + 64*64;
    __nv_bfloat16* smem_K0_0 = smem_Q1 + 64*64;
    __nv_bfloat16* smem_K0_1 = smem_K0_0 + 64*64;
    __nv_bfloat16* smem_K1_0 = smem_K0_1 + 64*64;
    __nv_bfloat16* smem_K1_1 = smem_K1_0 + 64*64;
    __nv_bfloat16* smem_V0_0 = smem_K1_1 + 64*64;
    __nv_bfloat16* smem_V0_1 = smem_V0_0 + 64*64;
    __nv_bfloat16* smem_V1_0 = smem_V0_1 + 64*64;
    __nv_bfloat16* smem_V1_1 = smem_V1_0 + 64*64;

    __nv_bfloat16* smem_P0 = smem_V1_1 + 64*64;
    __nv_bfloat16* smem_P1 = smem_P0 + 64*64;

    uintptr_t barrier_ptr = reinterpret_cast<uintptr_t>(smem_P1 + 64 * 64);
    barrier_ptr = (barrier_ptr + 7) & ~7;
    uint64_t* mbarrier_Q = reinterpret_cast<uint64_t*>(barrier_ptr);
    uint64_t* mbarrier_KV = mbarrier_Q + 1;
    uint64_t* mbarrier_empty = mbarrier_KV + 2;

    int tid = threadIdx.x;
    if (tid == 0) {
        init_smem_barrier_fn(mbarrier_Q, 1);
        init_smem_barrier_fn(&mbarrier_KV[0], 1);
        init_smem_barrier_fn(&mbarrier_KV[1], 1);
        init_smem_barrier_fn(&mbarrier_empty[0], 1);
        init_smem_barrier_fn(&mbarrier_empty[1], 1);
    }
    __syncthreads();
    fence_smem_barrier_init_fn();
    __syncthreads();

    if (tid == 0) {
        mbarrier_arrive_and_expect_tx_fn(mbarrier_Q, 16384);
        tma_load_3d_fn(&tma_Q, mbarrier_Q, smem_Q0, 0, base_row, bh_idx);
        tma_load_3d_fn(&tma_Q, mbarrier_Q, smem_Q1, 64, base_row, bh_idx);
    }

    int num_iters = (S + 63) / 64;
    int causal_num_iters = (base_row + 127) / 64 + 1;
    if (causal_num_iters < num_iters) {
        num_iters = causal_num_iters;
    }

    if (tid == 0 && num_iters > 0) {
        mbarrier_arrive_and_expect_tx_fn(&mbarrier_KV[0], 32768);
        tma_load_3d_fn(&tma_K, &mbarrier_KV[0], smem_K0_0, 0, 0, bh_idx);
        tma_load_3d_fn(&tma_K, &mbarrier_KV[0], smem_K0_1, 64, 0, bh_idx);
        tma_load_3d_fn(&tma_V, &mbarrier_KV[0], smem_V0_0, 0, 0, bh_idx);
        tma_load_3d_fn(&tma_V, &mbarrier_KV[0], smem_V0_1, 64, 0, bh_idx);
    }

    float acc_O0[32], acc_O1[32];
    #pragma unroll
    for(int i=0; i<32; i++){ acc_O0[i] = 0.0f; acc_O1[i] = 0.0f; }

    float m_A = -INFINITY, m_B = -INFINITY;
    float l_A = 0.0f, l_B = 0.0f;

    mbarrier_wait_fn(mbarrier_Q, 0);
    __syncthreads();

    for (int iter = 0; iter < num_iters; ++iter) {
        int s = iter % 2;
        int next_s = (iter + 1) % 2;

        int phase_kv = (iter / 2) & 1;
        mbarrier_wait_fn(&mbarrier_KV[s], phase_kv);
        __syncthreads();

        if (iter + 1 < num_iters && tid == 0) {
            int next_kv_base_row = (iter + 1) * 64;
            __nv_bfloat16* s_K0 = next_s == 0 ? smem_K0_0 : smem_K1_0;
            __nv_bfloat16* s_K1 = next_s == 0 ? smem_K0_1 : smem_K1_1;
            __nv_bfloat16* s_V0 = next_s == 0 ? smem_V0_0 : smem_V1_0;
            __nv_bfloat16* s_V1 = next_s == 0 ? smem_V0_1 : smem_V1_1;

            int phase_empty = ((iter - 1) / 2) & 1;
            mbarrier_wait_fn(&mbarrier_empty[next_s], phase_empty);

            mbarrier_arrive_and_expect_tx_fn(&mbarrier_KV[next_s], 32768);
            tma_load_3d_fn(&tma_K, &mbarrier_KV[next_s], s_K0, 0, next_kv_base_row, bh_idx);
            tma_load_3d_fn(&tma_K, &mbarrier_KV[next_s], s_K1, 64, next_kv_base_row, bh_idx);
            tma_load_3d_fn(&tma_V, &mbarrier_KV[next_s], s_V0, 0, next_kv_base_row, bh_idx);
            tma_load_3d_fn(&tma_V, &mbarrier_KV[next_s], s_V1, 64, next_kv_base_row, bh_idx);
        }

        float acc_S0[32], acc_S1[32];
        #pragma unroll
        for(int i=0; i<32; i++){ acc_S0[i] = 0.0f; acc_S1[i] = 0.0f; }

        wgmma_fence_fn();
        fence_proxy_async_fn();

        __nv_bfloat16* s_K0 = s == 0 ? smem_K0_0 : smem_K1_0;
        __nv_bfloat16* s_K1 = s == 0 ? smem_K0_1 : smem_K1_1;

        #pragma unroll
        for(int k=0; k<4; k++){
            uint64_t dQ0 = make_wgmma_desc(smem_Q0 + k * 16, 1, 1024, 1);
            uint64_t dK0 = make_wgmma_desc(s_K0 + k * 16, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc_S0, dQ0, dK0);
        }
        #pragma unroll
        for(int k=0; k<4; k++){
            uint64_t dQ1 = make_wgmma_desc(smem_Q1 + k * 16, 1, 1024, 1);
            uint64_t dK1 = make_wgmma_desc(s_K1 + k * 16, 1, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 0>(acc_S1, dQ1, dK1);
        }

        wgmma_commit_fn();
        wgmma_wait_fn<0>();
        __syncthreads();

        int kv_base_row = iter * 64;
        float max_A = -INFINITY, max_B = -INFINITY;
        float scale_inv = 1.0f / sqrtf(128.0f);

        #pragma unroll
        for(int r=0; r<32; r++){
            int row, col;
            get_d_coord_(tid, r, row, col);
            int global_row0 = base_row + row;
            int global_row1 = base_row + 64 + row;
            int global_col = kv_base_row + col;

            float S_val0 = acc_S0[r] * scale_inv;
            if (global_col > global_row0 || global_col >= S || global_row0 >= S) {
                S_val0 = -INFINITY;
            }
            acc_S0[r] = S_val0;

            float S_val1 = acc_S1[r] * scale_inv;
            if (global_col > global_row1 || global_col >= S || global_row1 >= S) {
                S_val1 = -INFINITY;
            }
            acc_S1[r] = S_val1;

            int r1 = (r / 2) % 2;
            if (r1 == 0) max_A = fmaxf(max_A, fmaxf(S_val0, S_val1));
            else         max_B = fmaxf(max_B, fmaxf(S_val0, S_val1));
        }

        #pragma unroll
        for(int mask=1; mask<4; mask*=2){
            max_A = fmaxf(max_A, __shfl_xor_sync(0xffffffff, max_A, mask));
            max_B = fmaxf(max_B, __shfl_xor_sync(0xffffffff, max_B, mask));
        }

        float m_old_A = m_A;
        float m_old_B = m_B;
        m_A = fmaxf(m_A, max_A);
        m_B = fmaxf(m_B, max_B);

        float exp_old_A = fast_exp2f_fn((m_old_A - m_A) * 1.4426950408889634f);
        float exp_old_B = fast_exp2f_fn((m_old_B - m_B) * 1.4426950408889634f);

        #pragma unroll
        for(int r=0; r<32; r++){
            int r1 = (r / 2) % 2;
            float exp_old = (r1 == 0) ? exp_old_A : exp_old_B;
            acc_O0[r] *= exp_old;
            acc_O1[r] *= exp_old;
        }

        float sum_A = 0.0f, sum_B = 0.0f;
        #pragma unroll
        for(int r=0; r<32; r++){
            int r1 = (r / 2) % 2;
            float m_curr = (r1 == 0) ? m_A : m_B;
            float exp_val0 = fast_exp2f_fn((acc_S0[r] - m_curr) * 1.4426950408889634f);
            acc_S0[r] = exp_val0;
            float exp_val1 = fast_exp2f_fn((acc_S1[r] - m_curr) * 1.4426950408889634f);
            acc_S1[r] = exp_val1;

            if (r1 == 0) sum_A += exp_val0 + exp_val1;
            else         sum_B += exp_val0 + exp_val1;
        }

        #pragma unroll
        for(int mask=1; mask<4; mask*=2){
            sum_A += __shfl_xor_sync(0xffffffff, sum_A, mask);
            sum_B += __shfl_xor_sync(0xffffffff, sum_B, mask);
        }

        l_A = l_A * exp_old_A + sum_A;
        l_B = l_B * exp_old_B + sum_B;

        store_acc_smem_64x64_swizzle(smem_P0, acc_S0, tid);
        store_acc_smem_64x64_swizzle(smem_P1, acc_S1, tid);
        __syncthreads();

        wgmma_fence_fn();
        fence_proxy_async_fn();

        __nv_bfloat16* s_V0 = s == 0 ? smem_V0_0 : smem_V1_0;
        __nv_bfloat16* s_V1 = s == 0 ? smem_V0_1 : smem_V1_1;

        #pragma unroll
        for(int k=0; k<4; k++){
            uint64_t dP0 = make_wgmma_desc(smem_P0 + k * 16, 1, 1024, 1);
            uint64_t dV0 = make_wgmma_desc(s_V0 + k * 1024, 8192, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 1>(acc_O0, dP0, dV0);

            uint64_t dP1 = make_wgmma_desc(smem_P1 + k * 16, 1, 1024, 1);
            uint64_t dV1 = make_wgmma_desc(s_V1 + k * 1024, 8192, 1024, 1);
            wgmma_m64n64k16_ss_fn<0, 1>(acc_O1, dP1, dV1);
        }

        wgmma_commit_fn();
        wgmma_wait_fn<0>();

        if (tid == 0) {
            mbarrier_arrive_fn(&mbarrier_empty[s]);
        }
        __syncthreads();
    }

    #pragma unroll
    for(int r=0; r<32; r++){
        int r1 = (r / 2) % 2;
        float inv_l = (r1 == 0) ? (1.0f / l_A) : (1.0f / l_B);
        acc_O0[r] *= inv_l;
        acc_O1[r] *= inv_l;
    }

    __syncthreads();

    store_acc_global_n128_fn(O_ptr, acc_O0, base_row, 0, B, H, S, D, tid, bh_idx);
    store_acc_global_n128_fn(O_ptr, acc_O1, base_row + 64, 0, B, H, S, D, tid, bh_idx);

    __syncthreads();

    int lane_id = tid % 32;
    if (lane_id % 4 == 0) {
        int t1 = (tid / 4) % 8;
        int t2 = tid / 32;
        int row_A = (t1 + t2 * 16) % 64;
        int row_B = (t1 + t2 * 16 + 8) % 64;

        if (base_row + row_A < S) {
            float lse_A = m_A + logf(l_A);
            LSE_ptr[bh_idx * S + base_row + row_A] = lse_A;
        }
        if (base_row + row_B < S) {
            float lse_B = m_B + logf(l_B);
            LSE_ptr[bh_idx * S + base_row + row_B] = lse_B;
        }
        if (base_row + 64 + row_A < S) {
            float lse_A = m_A + logf(l_A);
            LSE_ptr[bh_idx * S + base_row + 64 + row_A] = lse_A;
        }
        if (base_row + 64 + row_B < S) {
            float lse_B = m_B + logf(l_B);
            LSE_ptr[bh_idx * S + base_row + 64 + row_B] = lse_B;
        }
    }
}

void run(tvm::ffi::TensorView Q, tvm::ffi::TensorView K, tvm::ffi::TensorView V, tvm::ffi::TensorView O, tvm::ffi::TensorView LSE) {
    CUDA_CHECK(cudaSetDevice(Q.device().device_id));

    int64_t B = Q.size(0);
    int64_t H = Q.size(1);
    int64_t S = Q.size(2);
    int64_t D = Q.size(3);

    void* q_data = Q.data_ptr();
    void* k_data = K.data_ptr();
    void* v_data = V.data_ptr();
    __nv_bfloat16* o_data = static_cast<__nv_bfloat16*>(O.data_ptr());
    float* lse_data = static_cast<float*>(LSE.data_ptr());

    CUtensorMap tma_Q, tma_K, tma_V;
    if (create_tma_3d_descriptor_2B(&tma_Q, q_data, D, S, B * H, 64, 64, 1, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) exit(1);
    if (create_tma_3d_descriptor_2B(&tma_K, k_data, D, S, B * H, 64, 64, 1, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) exit(1);
    if (create_tma_3d_descriptor_2B(&tma_V, v_data, D, S, B * H, 64, 64, 1, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_NONE, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) exit(1);

    int smem_size = 12 * 64 * 64 * 2 + 1024;
    CUDA_CHECK(cudaFuncSetAttribute(causal_mha_fwd, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size));

    dim3 grid((S + 127) / 128, H, B);
    dim3 block(128);
    cudaStream_t stream = static_cast<cudaStream_t>(TVMFFIEnvGetStream(Q.device().device_type, Q.device().device_id));

    causal_mha_fwd<<<grid, block, smem_size, stream>>>(tma_Q, tma_K, tma_V, o_data, lse_data, S, B, H, D);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaStreamSynchronize(stream));
}

TVM_FFI_DLL_EXPORT_TYPED_FUNC(run, tvm_ffi_cuda_kernel::run);

